import { useState, useRef, useEffect } from 'react';

export default function ARKDemo() {
 const [messages, setMessages] = useState([{ role: 'assistant', content: 'Bonjour. Je suis ARK, l\'assistant IA natif de COURTIA. Posez-moi une question sur la gestion de votre portefeuille d\'assurance.' }]);
 const [input, setInput] = useState('');
 const [_loading, _setLoading] = useState(false);
 const [thinking, setThinking] = useState(false);
 const messagesEndRef = useRef(null);
 const anthropicApiKey = import.meta.env.VITE_ANTHROPIC_API_KEY || ''

 useEffect(() => {
 messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
 }, [messages]);

 const sendToARK = async (prompt) => {
 if (!prompt.trim()) return;

 setMessages(prev => [...prev, { role: 'user', content: prompt }]);
 setInput('');
 setThinking(true);

 try {
 const response = await fetch('https://api.anthropic.com/v1/messages', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'x-api-key': anthropicApiKey,
 'anthropic-version': '2023-06-01'
 },
 body: JSON.stringify({
 model: 'claude-3-5-sonnet-20241022',
 max_tokens: 512,
 system: `Tu es ARK, l'IA native de COURTIA, un CRM pour courtiers d'assurance français.
Tu es en démo sur la landing page de COURTIA.
Réponds en français, de façon concise et professionnelle (max 3 lignes).
Montre ta valeur métier pour un courtier d'assurance.`,
 messages: messages.map(m => ({ role: m.role, content: m.content })).concat([{ role: 'user', content: prompt }]),
 stream: true
 })
 });

 if (!response.ok) {
 setThinking(false);
 setMessages(prev => [...prev, { role: 'assistant', content: 'Erreur API. Réessayez.' }]);
 return;
 }

 const reader = response.body.getReader();
 const decoder = new TextDecoder();
 let fullResponse = '';
 setThinking(false);

 let done = false;
 while (!done) {
 const { done: streamDone, value } = await reader.read();
 done = streamDone;
 if (!value) continue;

 const chunk = decoder.decode(value);
 const lines = chunk.split('\n');

 for (const line of lines) {
 if (line.startsWith('data: ')) {
 try {
 const data = JSON.parse(line.slice(6));
 if (data.type === 'content_block_delta' && data.delta?.type === 'text_delta') {
 fullResponse += data.delta.text;
 setMessages(prev => {
 const last = prev[prev.length - 1];
 if (last?.role === 'assistant') {
 return [...prev.slice(0, -1), { role: 'assistant', content: fullResponse }];
 }
 return [...prev, { role: 'assistant', content: fullResponse }];
 });
 }
 } catch (_e) {
 // skip
 }
 }
 }
 }
 } catch (err) {
 console.error('Erreur:', err);
 setThinking(false);
 }
 };

 const suggestions = [
 'Analyse un client qui risque de résilier',
 'Rédige un email de relance',
 'Quelles opportunités cross-sell ?'
 ];

 return (
 <div style={{ display: 'flex', flexDirection: 'column', height: '100%', gap: '16px' }}>
 {/* Messages */}
 <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '10px', maxHeight: '300px' }}>
 {messages.map((msg, i) => (
 <div key={i} style={{ display: 'flex', justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start' }}>
 <div style={{ padding: '10px 13px', borderRadius: msg.role === 'user' ? '10px 4px 10px 10px' : '4px 10px 10px 10px', fontSize: '12px', lineHeight: '1.6', background: msg.role === 'user' ? 'rgba(37,99,235,0.15)' : 'rgba(255,255,255,0.04)', color: msg.role === 'user' ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.75)', border: msg.role === 'user' ? '0.5px solid rgba(37,99,235,0.2)' : '0.5px solid rgba(255,255,255,0.05)', maxWidth: '85%' }}>
 {msg.content}
 </div>
 </div>
 ))}
 {thinking && (
 <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: 'rgba(255,255,255,0.3)', fontSize: '11px' }}>
 <div style={{ display: 'flex', gap: '3px' }}>
 {[0, 1, 2].map(i => (
 <div key={i} style={{ width: '4px', height: '4px', borderRadius: '50%', background: 'rgba(37,99,235,0.5)', animation: `dotBounce 1.2s ease ${i * 0.2}s infinite` }}></div>
 ))}
 </div>
 ARK réfléchit...
 </div>
 )}
 <div ref={messagesEndRef} />
 </div>

 {/* Suggestions */}
 <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
 {suggestions.map(sug => (
 <button key={sug} onClick={() => sendToARK(sug)} disabled={thinking} style={{ padding: '8px 12px', background: 'rgba(255,255,255,0.04)', border: '0.5px solid rgba(255,255,255,0.08)', borderRadius: '6px', color: 'rgba(255,255,255,0.5)', fontSize: '11px', fontWeight: '600', cursor: 'pointer', textAlign: 'left', transition: 'all 0.2s' }} onMouseEnter={(e) => { e.target.style.background = 'rgba(255,255,255,0.08)'; e.target.style.color = 'rgba(255,255,255,0.8)'; }} onMouseLeave={(e) => { e.target.style.background = 'rgba(255,255,255,0.04)'; e.target.style.color = 'rgba(255,255,255,0.5)'; }}>
 💭 {sug}
 </button>
 ))}
 </div>

 {/* Input */}
 <div style={{ display: 'flex', gap: '8px' }}>
 <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && sendToARK(input)} placeholder="Posez à ARK..." style={{ flex: 1, background: 'rgba(255,255,255,0.04)', border: '0.5px solid rgba(255,255,255,0.08)', borderRadius: '6px', padding: '8px 12px', fontSize: '11px', color: '#fff', fontFamily: 'Arial' }} />
 <button onClick={() => sendToARK(input)} disabled={!input.trim() || thinking} style={{ background: '#2563eb', borderRadius: '6px', padding: '8px 12px', fontSize: '11px', color: '#fff', border: 'none', cursor: 'pointer', fontWeight: '700' }}>→</button>
 </div>

 <style>{`
 @keyframes dotBounce {
 0%, 80%, 100% { transform: translateY(0); }
 40% { transform: translateY(-5px); }
 }
 `}</style>
 </div>
 );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const NIVEAUX_COLORS = { debutant:'text-green-400', intermediaire:'text-amber-400', avance:'text-red-400' };

export default function ArkFormateur() {
  const [modules, setModules] = useState([]);
  const [progression, setProgression] = useState(null);
  const [activeQuiz, setActiveQuiz] = useState(null);
  const [reponses, setReponses] = useState({});
  const [result, setResult] = useState(null);
  const [quizStep, setQuizStep] = useState(0);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  useEffect(() => {
    fetch(`${API}/api/formation/modules`, { headers }).then(r => r.json()).then(setModules);
    fetch(`${API}/api/formation/progression`, { headers }).then(r => r.json()).then(setProgression);
  }, []);

  function startQuiz(mod) {
    setActiveQuiz(mod);
    setReponses({});
    setResult(null);
    setQuizStep(0);
  }

  async function submitQuiz() {
    const reponsesArray = activeQuiz.questions.map((_, i) => reponses[i] ?? -1);
    const res = await fetch(`${API}/api/formation/modules/${activeQuiz.id}/submit`, {
      method: "POST", headers, body: JSON.stringify({ reponses: reponsesArray })
    });
    const data = await res.json();
    setResult(data);
    if (data.termine) {
      setProgression(prev => ({ ...prev, modules_termines: (prev?.modules_termines || 0) + 1 }));
    }
  }

  if (activeQuiz && !result) {
    const q = activeQuiz.questions[quizStep];
    return (
      <div className="p-6 space-y-6">
        <div className="flex justify-between items-center">
          <h2 className="text-lg font-semibold text-white">{activeQuiz.titre}</h2>
          <button onClick={() => setActiveQuiz(null)} className="text-gray-400 hover:text-white text-sm">✕ Quitter</button>
        </div>

        {/* Progress */}
        <div>
          <div className="flex justify-between text-xs text-gray-400 mb-1">
            <span>Question {quizStep + 1} / {activeQuiz.questions.length}</span>
            <span>{Math.round((quizStep / activeQuiz.questions.length) * 100)}%</span>
          </div>
          <div className="w-full bg-gray-700 rounded-full h-2">
            <div className="bg-cyan-400 h-2 rounded-full transition-all" style={{ width: `${(quizStep / activeQuiz.questions.length) * 100}%` }} />
          </div>
        </div>

        <div className="bg-gray-800/60 rounded-xl p-5 border border-gray-700">
          <p className="text-white font-medium mb-4">{q.q}</p>
          <div className="space-y-2">
            {q.options.map((opt, i) => (
              <button key={i} onClick={() => setReponses(r => ({ ...r, [quizStep]: i }))}
                className={`w-full text-left px-4 py-3 rounded-lg border text-sm transition ${
                  reponses[quizStep] === i
                    ? 'border-cyan-500 bg-cyan-900/30 text-cyan-300'
                    : 'border-gray-600 text-gray-300 hover:border-gray-500 hover:bg-gray-700/30'
                }`}>
                <span className="text-gray-500 mr-2">{['A','B','C','D'][i]}.</span>{opt}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-3">
          {quizStep > 0 && (
            <button onClick={() => setQuizStep(s => s - 1)} className="px-4 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">← Précédent</button>
          )}
          {quizStep < activeQuiz.questions.length - 1 ? (
            <button onClick={() => setQuizStep(s => s + 1)} disabled={reponses[quizStep] === undefined}
              className="flex-1 py-2 rounded-lg bg-cyan-500 text-black font-medium text-sm disabled:opacity-50">
              Suivant →
            </button>
          ) : (
            <button onClick={submitQuiz} disabled={Object.keys(reponses).length < activeQuiz.questions.length}
              className="flex-1 py-2 rounded-lg bg-green-500 text-black font-medium text-sm disabled:opacity-50">
              ✓ Terminer le quiz
            </button>
          )}
        </div>
      </div>
    );
  }

  if (result) {
    return (
      <div className="p-6 space-y-6">
        <div className="text-center">
          <p className="text-5xl mb-3">{result.termine ? '🎓' : '📚'}</p>
          <p className={`text-2xl font-bold ${result.termine ? 'text-green-400' : 'text-amber-400'}`}>{result.score}/100</p>
          <p className="text-gray-300 mt-1">{result.correct}/{result.total} bonnes réponses</p>
          {result.termine ? (
            <p className="text-green-400 text-sm mt-2">Module validé ! Certificat disponible au téléchargement.</p>
          ) : (
            <p className="text-amber-400 text-sm mt-2">Score minimum de 70 requis. Réessaie !</p>
          )}
        </div>

        <div className="space-y-3">
          {result.details?.map((d, i) => (
            <div key={i} className={`rounded-lg p-3 border ${d.correct ? 'border-green-700/40 bg-green-900/10' : 'border-red-700/40 bg-red-900/10'}`}>
              <div className="flex items-start gap-2">
                <span>{d.correct ? '✅' : '❌'}</span>
                <div>
                  <p className="text-xs text-gray-300">{d.question}</p>
