import { useState, useEffect } from 'react'
import { Plus, Edit2, Trash2, AlertCircle } from 'lucide-react'
import { useAuthStore } from '../stores/authStore'

const API_URL = import.meta.env.VITE_API_URL || '/api'

export default function Contrats() {
  const token = useAuthStore((state) => state.token)
  const [contrats, setContrats] = useState([])
  const [loading, setLoading] = useState(true)
  const [_error, setError] = useState(null)
  const [showModal, setShowModal] = useState(false)
  const [selectedForEdit, setSelectedForEdit] = useState(null)
  const [filterStatus, setFilterStatus] = useState('tous')
  const [clients, setClients] = useState([])
  const [formData, setFormData] = useState({
    client_id: '',
    type_contrat: 'auto',
    compagnie: '',
    numero: '',
    prime_annuelle: '',
    date_effet: '',
    date_echeance: '',
    statut: 'actif'
  })

  // Load contrats and clients
  useEffect(() => {
    if (token) {
      fetchContrats()
      fetchClients()
    }
  }, [token])

  const fetchContrats = async () => {
    try {
      const res = await fetch(`${API_URL}/api/contracts`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await res.json()
      setContrats(Array.isArray(data) ? data : data.contracts || [])
      setError(null)
    } catch (err) {
      console.error('Error fetching contrats:', err)
      setError('Erreur lors du chargement des contrats')
    } finally {
      setLoading(false)
    }
  }

  const fetchClients = async () => {
    try {
      const res = await fetch(`${API_URL}/api/clients`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await res.json()
      setClients(Array.isArray(data) ? data : data.clients || [])
    } catch (err) {
      console.error('Error fetching clients:', err)
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      const method = selectedForEdit ? 'PUT' : 'POST'
      const endpoint = selectedForEdit ? `/api/contracts/${selectedForEdit.id}` : '/api/contracts'

      const res = await fetch(`${API_URL}${endpoint}`, {
        method,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          client_id: parseInt(formData.client_id),
          type_contrat: formData.type_contrat,
          compagnie: formData.compagnie,
          numero: formData.numero,
          prime_annuelle: parseFloat(formData.prime_annuelle),
          date_effet: formData.date_effet,
          date_echeance: formData.date_echeance,
          statut: formData.statut
        })
      })

      if (res.ok) {
        fetchContrats()
        setShowModal(false)
        setSelectedForEdit(null)
        setFormData({
          client_id: '',
          type_contrat: 'auto',
          compagnie: '',
          numero: '',
          prime_annuelle: '',
          date_effet: '',
          date_echeance: '',
          statut: 'actif'
        })
      }
    } catch (err) {
      console.error('Error saving contrat:', err)
    }
  }

  const handleDelete = async (id) => {
    if (!confirm('Confirmer la suppression ?')) return
    try {
      const res = await fetch(`${API_URL}/api/contracts/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      })
      if (res.ok) {
        fetchContrats()
      }
    } catch (err) {
      console.error('Error deleting contrat:', err)
    }
  }

  const handleEdit = (contrat) => {
    setSelectedForEdit(contrat)
    setFormData({
      client_id: contrat.client_id,
      type_contrat: contrat.type_contrat,
      compagnie: contrat.compagnie,
      numero: contrat.numero,
      prime_annuelle: contrat.prime_annuelle,
      date_effet: contrat.date_effet,
      date_echeance: contrat.date_echeance,
      statut: contrat.statut
    })
    setShowModal(true)
  }

  const getStatusBadge = (status, dateEcheance) => {
    const days = dateEcheance ? Math.ceil((new Date(dateEcheance) - new Date()) / (1000 * 60 * 60 * 24)) : null

    if (status === 'actif') {
      if (days && days < 30 && days > 0) {
        return { bg: '#fef3c7', color: '#d97706', label: '⚠ Bientôt', icon: '⚠️' }
      }
      return { bg: '#d1fae5', color: '#065f46', label: 'Actif', icon: '✓' }
    }
    if (status === 'résilié') {
      return { bg: '#fee2e2', color: '#dc2626', label: 'Résilié', icon: '✗' }
    }
    if (days && days <= 0) {
      return { bg: '#fee2e2', color: '#dc2626', label: 'Expiré', icon: '⚠️' }
    }
    return { bg: '#f3f4f6', color: '#6b7280', label: 'En attente', icon: '-' }
  }

  const filteredContrats = filterStatus === 'tous' 
    ? contrats 
    : contrats.filter(c => c.statut === filterStatus)

  if (loading) {
    return <div style={{padding:'32px'}}>Chargement...</div>
  }

  return (
    <div style={{padding:'32px',fontFamily:'Arial,sans-serif',background:'#fff'}}>
      {showModal && (
        <div style={{position:'fixed',top:0,left:0,right:0,bottom:0,background:'rgba(0,0,0,0.5)',display:'flex',alignItems:'center',justifyContent:'center',zIndex:1000}}>
          <div style={{background:'#fff',padding:'32px',borderRadius:'12px',width:'90%',maxWidth:'500px'}}>
            <h2 style={{fontSize:'20px',fontWeight:700,marginBottom:'20px'}}>{selectedForEdit ? 'Modifier' : 'Ajouter'} contrat</h2>
            <form onSubmit={handleSubmit} style={{display:'flex',flexDirection:'column',gap:'16px'}}>
              <div>
                <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Client *</label>
                <select 
                  value={formData.client_id} 
                  onChange={(e) => setFormData({...formData, client_id: e.target.value})}
                  required
                  style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                >
                  <option value=''>-- Sélectionner --</option>
                  {clients.map(c => (
                    <option key={c.id} value={c.id}>{`${c.first_name} ${c.last_name}`}</option>
                  ))}
                </select>
              </div>
              <div>
                <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Type contrat *</label>
                <select 
                  value={formData.type_contrat} 
                  onChange={(e) => setFormData({...formData, type_contrat: e.target.value})}
                  style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                >
                  <option value='auto'>Automobile</option>
                  <option value='habitation'>Habitation</option>
                  <option value='sante'>Santé</option>
                  <option value='prevoyance'>Prévoyance</option>
                  <option value='pro'>Professionnel</option>
                </select>
              </div>
              <div>
                <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Compagnie *</label>
                <input 
                  value={formData.compagnie} 
                  onChange={(e) => setFormData({...formData, compagnie: e.target.value})}
                  required
                  style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                />
              </div>
              <div>
                <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Numéro contrat</label>
                <input 
                  value={formData.numero} 
                  onChange={(e) => setFormData({...formData, numero: e.target.value})}
                  style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                />
              </div>
              <div>
                <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Prime annuelle (€)</label>
                <input 
                  type='number' 
                  step='0.01'
                  value={formData.prime_annuelle} 
                  onChange={(e) => setFormData({...formData, prime_annuelle: e.target.value})}
                  style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                />
              </div>
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'12px'}}>
                <div>
                  <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Date effet</label>
                  <input 
                    type='date'
                    value={formData.date_effet} 
                    onChange={(e) => setFormData({...formData, date_effet: e.target.value})}
                    style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                  />
                </div>
                <div>
                  <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Date échéance</label>
                  <input 
                    type='date'
                    value={formData.date_echeance} 
                    onChange={(e) => setFormData({...formData, date_echeance: e.target.value})}
                    style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                  />
                </div>
              </div>
              <div>
                <label style={{fontSize:'12px',fontWeight:600,color:'#666'}}>Statut</label>
                <select 
                  value={formData.statut} 
                  onChange={(e) => setFormData({...formData, statut: e.target.value})}
                  style={{width:'100%',padding:'8px 12px',border:'0.5px solid #ddd',borderRadius:'6px',marginTop:'4px',fontFamily:'Arial'}}
                >
                  <option value='actif'>Actif</option>
                  <option value='résilié'>Résilié</option>
                  <option value='en attente'>En attente</option>
                </select>
              </div>
              <div style={{display:'flex',gap:'12px',marginTop:'20px'}}>
                <button type='submit' style={{flex:1,padding:'10px',background:'#0a0a0a',color:'#fff',border:'none',borderRadius:'6px',fontWeight:600,cursor:'pointer'}}>
                  {selectedForEdit ? 'Modifier' : 'Créer'}
                </button>
                <button type='button' onClick={() => {setShowModal(false);setSelectedForEdit(null)}} style={{flex:1,padding:'10px',background:'#f0f0f0',color:'#0a0a0a',border:'none',borderRadius:'6px',fontWeight:600,cursor:'pointer'}}>
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:'32px'}}>
        <h2 style={{fontSize:'32px',fontWeight:900,color:'#0a0a0a'}}>Contrats</h2>
        <button onClick={() => {setSelectedForEdit(null);setShowModal(true)}} style={{display:'flex',alignItems:'center',gap:'8px',padding:'10px 20px',background:'#0a0a0a',color:'#fff',border:'none',borderRadius:'8px',fontSize:'13px',fontWeight:700,cursor:'pointer',fontFamily:'Arial'}}>
          <Plus size={18} />
          Ajouter contrat
        </button>
      </div>

      {/* Filters */}
      <div style={{display:'flex',gap:'8px',marginBottom:'24px'}}>
        {['tous', 'actif', 'résilié', 'en attente'].map(status => (
          <button key={status} onClick={() => setFilterStatus(status)} style={{padding:'8px 16px',background:filterStatus===status?'#0a0a0a':'#f0f0f0',color:filterStatus===status?'#fff':'#0a0a0a',border:'none',borderRadius:'6px',fontSize:'12px',fontWeight:600,cursor:'pointer'}}>
            {status.charAt(0).toUpperCase() + status.slice(1)}
          </button>
        ))}
      </div>

      {/* Table */}
      <div style={{border:'0.5px solid #f0f0f0',borderRadius:'10px',overflow:'hidden'}}>
        <table style={{width:'100%',borderCollapse:'collapse'}}>
          <thead>
            <tr style={{background:'#0a0a0a',height:'44px'}}>
              <th style={{padding:'12px 16px',textAlign:'left',fontSize:'12px',fontWeight:700,color:'#fff'}}>Client</th>
              <th style={{padding:'12px 16px',textAlign:'left',fontSize:'12px',fontWeight:700,color:'#fff'}}>Type</th>
              <th style={{padding:'12px 16px',textAlign:'left',fontSize:'12px',fontWeight:700,color:'#fff'}}>Compagnie</th>
              <th style={{padding:'12px 16px',textAlign:'left',fontSize:'12px',fontWeight:700,color:'#fff'}}>Prime</th>
              <th style={{padding:'12px 16px',textAlign:'left',fontSize:'12px',fontWeight:700,color:'#fff'}}>Échéance</th>
              <th style={{padding:'12px 16px',textAlign:'left',fontSize:'12px',fontWeight:700,color:'#fff'}}>Statut</th>
              <th style={{padding:'12px 16px',textAlign:'center',fontSize:'12px',fontWeight:700,color:'#fff'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredContrats.map((contrat, idx) => {
              const client = clients.find(c => c.id === contrat.client_id)
              const badge = getStatusBadge(contrat.statut, contrat.date_echeance)
              return (
                <tr key={contrat.id} style={{borderTop:'0.5px solid #f0f0f0',height:'48px',background:idx%2===0?'#fff':'#fafafa'}}>
                  <td style={{padding:'12px 16px',fontSize:'13px',fontWeight:500}}>{client ? `${client.first_name} ${client.last_name}` : 'N/A'}</td>
                  <td style={{padding:'12px 16px',fontSize:'13px'}}>{contrat.type_contrat}</td>
                  <td style={{padding:'12px 16px',fontSize:'13px'}}>{contrat.compagnie}</td>
                  <td style={{padding:'12px 16px',fontSize:'13px',fontWeight:600}}>{contrat.prime_annuelle}€</td>
                  <td style={{padding:'12px 16px',fontSize:'13px'}}>
                    {contrat.date_echeance && (
                      <div>
                        {new Date(contrat.date_echeance).toLocaleDateString('fr-FR')}
                        {Math.ceil((new Date(contrat.date_echeance) - new Date()) / (1000 * 60 * 60 * 24)) < 30 && (
                          <AlertCircle size={14} style={{display:'inline',marginLeft:'6px',color:'#f59e0b'}} />
                        )}
                      </div>
                    )}
                  </td>
                  <td style={{padding:'12px 16px'}}>
                    <span style={{padding:'4px 10px',borderRadius:'6px',background:badge.bg,color:badge.color,fontSize:'12px',fontWeight:600}}>
                      {badge.label}
                    </span>
                  </td>
                  <td style={{padding:'12px 16px',textAlign:'center',display:'flex',alignItems:'center',justifyContent:'center',gap:'8px'}}>
                    <button onClick={() => handleEdit(contrat)} style={{background:'none',border:'none',cursor:'pointer',color:'#666',padding:'4px'}}>
                      <Edit2 size={16} />
                    </button>
                    <button onClick={() => handleDelete(contrat.id)} style={{background:'none',border:'none',cursor:'pointer',color:'#ef4444',padding:'4px'}}>
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>

      {filteredContrats.length === 0 && (
        <div style={{textAlign:'center',padding:'48px 24px',color:'#999'}}>
          <p style={{fontSize:'14px'}}>Aucun contrat trouvé</p>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const STATUT_COLORS = { nouvelle:'bg-blue-900/50 text-blue-300', contacte:'bg-amber-900/50 text-amber-300', convertie:'bg-green-900/50 text-green-300', ignoree:'bg-gray-700 text-gray-400' };

export default function CrossSellDashboard() {
  const [opportunites, setOpportunites] = useState([]);
  const [stats, setStats] = useState(null);
  const [scanning, setScanning] = useState(false);
  const [filter, setFilter] = useState("nouvelle");
  const [selected, setSelected] = useState(null);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  const load = async (statut) => {
    fetch(`${API}/api/cross-sell/opportunites?statut=${statut}`, { headers }).then(r => r.json()).then(setOpportunites);
    fetch(`${API}/api/cross-sell/stats`, { headers }).then(r => r.json()).then(setStats);
  };

  useEffect(() => { load(filter); }, []);

  async function scan() {
    setScanning(true);
    const res = await fetch(`${API}/api/cross-sell/scan`, { method: "POST", headers });
    const result = await res.json();
    setScanning(false);
    alert(`✅ ${result.total_opportunites} nouvelles opportunités détectées · CA potentiel : ${Math.round(result.ca_potentiel)} €`);
    load(filter);
  }

  async function updateStatut(id, statut) {
    await fetch(`${API}/api/cross-sell/opportunites/${id}`, { method: "PATCH", headers, body: JSON.stringify({ statut }) });
    setOpportunites(prev => prev.filter(o => o.id !== id));
  }

  const caTotal = parseFloat(stats?.ca_potentiel || 0);

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">💎 Cross-sell Intelligence</h2>
          <p className="text-sm text-gray-400 mt-1">ARK détecte les produits manquants dans ton portefeuille</p>
        </div>
        <button onClick={scan} disabled={scanning}
          className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-2 rounded-lg text-sm transition disabled:opacity-50">
          {scanning ? "⚡ Analyse en cours..." : "🔍 Scanner le portefeuille"}
        </button>
      </div>

      {stats && (
        <div className="grid grid-cols-4 gap-3">
          {[
            { label: "Nouvelles", val: stats.nouvelles || 0, color: "text-blue-400" },
            { label: "Contactées", val: stats.contactees || 0, color: "text-amber-400" },
            { label: "Converties", val: stats.converties || 0, color: "text-green-400" },
            { label: "CA potentiel", val: `${Math.round(caTotal)} €`, color: "text-cyan-400" },
          ].map(s => (
            <div key={s.label} className="bg-gray-800/60 rounded-xl p-3 border border-gray-700 text-center">
              <p className={`text-xl font-bold ${s.color}`}>{s.val}</p>
              <p className="text-xs text-gray-500 mt-0.5">{s.label}</p>
            </div>
          ))}
        </div>
      )}

      {/* Filtres */}
      <div className="flex gap-2">
        {["nouvelle","contacte","convertie","ignoree"].map(s => (
          <button key={s} onClick={() => { setFilter(s); load(s); }}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition border ${filter===s?'border-cyan-500 text-cyan-400 bg-cyan-900/20':'border-gray-700 text-gray-400'}`}>
            {s}
          </button>
        ))}
      </div>

      {/* Opportunités */}
      {opportunites.length === 0 && (
        <div className="text-center py-12">
          <p className="text-4xl mb-3">💎</p>
          <p className="text-gray-500 text-sm">Aucune opportunité en statut "{filter}".</p>
          <p className="text-gray-600 text-xs mt-1">Clique "Scanner le portefeuille" pour détecter de nouvelles opportunités.</p>
        </div>
      )}

      <div className="space-y-3">
        {opportunites.map(o => (
          <div key={o.id} className="bg-gray-800/40 rounded-xl border border-gray-700/50 overflow-hidden">
            <div className="p-4 cursor-pointer" onClick={() => setSelected(selected?.id === o.id ? null : o)}>
              <div className="flex justify-between items-start">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <p className="text-sm font-medium text-white">{o.client_nom}</p>
                    <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${STATUT_COLORS[o.statut]}`}>{o.statut}</span>
                  </div>
                  <p className="text-xs text-amber-400 font-medium">{o.type_opportunite}</p>
                  <p className="text-xs text-gray-400 mt-0.5">Produit manquant : <span className="text-white">{o.produit_manquant}</span></p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-green-400">{parseFloat(o.commission_estimee||0).toFixed(0)} €</p>
                  <p className="text-xs text-gray-500">commission est.</p>
                  <div className="flex items-center gap-1 mt-1 justify-end">
                    <div className="w-12 bg-gray-700 rounded-full h-1">
                      <div className="bg-cyan-400 h-1 rounded-full" style={{ width: `${o.score_potentiel}%` }} />
                    </div>
                    <span className="text-xs text-gray-400">{o.score_potentiel}</span>
                  </div>
                </div>
              </div>
            </div>

            {selected?.id === o.id && (
              <div className="border-t border-gray-700 p-4 space-y-3">
                <div className="bg-gray-900/50 rounded-lg p-3 border border-gray-700/30">
                  <p className="text-xs text-cyan-400 mb-1">💬 Message personnalisé ARK</p>
                  <p className="text-sm text-gray-200 italic">"{o.message_personnalise}"</p>
                </div>
                <div className="flex gap-2">
                  {o.client_email && (
                    <a href={`mailto:${o.client_email}?subject=Votre couverture assurance&body=${encodeURIComponent(o.message_personnalise)}`}
                      className="flex-1 py-2 rounded-lg bg-blue-700 hover:bg-blue-600 text-white text-sm text-center transition">
                      📧 Email
                    </a>
                  )}
                  {o.client_tel && (
                    <a href={`tel:${o.client_tel}`}
                      className="flex-1 py-2 rounded-lg bg-green-700 hover:bg-green-600 text-white text-sm text-center transition">
                      📞 Appeler
                    </a>
                  )}
                  <button onClick={() => updateStatut(o.id, 'contacte')}
                    className="flex-1 py-2 rounded-lg bg-amber-600 hover:bg-amber-500 text-white text-sm transition">
                    ✓ Contacté
                  </button>
                  <button onClick={() => updateStatut(o.id, 'convertie')}
                    className="flex-1 py-2 rounded-lg bg-green-600 hover:bg-green-500 text-white text-sm transition">
                    💰 Converti
                  </button>
                  <button onClick={() => updateStatut(o.id, 'ignoree')}
                    className="py-2 px-3 rounded-lg border border-gray-600 text-gray-400 text-sm">
                    ✕
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const CAT_ICONS = { devoir_conseil:"📋", conformite:"⚖️", iard:"🚗", sante:"🏥", prevoyance:"🛡️" };

export default function DDAFormateur() {
  const [dashboard, setDashboard] = useState(null);
  const [quiz, setQuiz] = useState(null);
  const [reponses, setReponses] = useState({});
  const [resultat, setResultat] = useState(null);
  const [tips, setTips] = useState(null);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  useEffect(() => {
    fetch(`${API}/api/dda/dashboard`, { headers }).then(r => r.json()).then(setDashboard);
    fetch(`${API}/api/dda/tips`, { headers }).then(r => r.json()).then(setTips);
  }, []);

  async function startQuiz(categorie = null) {
    const res = await fetch(`${API}/api/dda/quiz/start`, {
      method: "POST", headers, body: JSON.stringify({ nb: 8, categorie })
    });
    const data = await res.json();
    setQuiz(data);
    setReponses({});
    setResultat(null);
  }

  async function submitQuiz() {
    const reponsesArray = Object.entries(reponses).map(([qId, rep]) => ({
      question_id: parseInt(qId), reponse: parseInt(rep)
    }));
    const res = await fetch(`${API}/api/dda/quiz/${quiz.session_id}/submit`, {
      method: "POST", headers, body: JSON.stringify({ reponses: reponsesArray })
    });
    const data = await res.json();
    setResultat(data);
    setQuiz(null);
    fetch(`${API}/api/dda/dashboard`, { headers }).then(r => r.json()).then(setDashboard);
  }

  const scoreColor = s => s >= 80 ? "text-green-400" : s >= 60 ? "text-amber-400" : "text-red-400";
  const scoreLabel = s => s >= 80 ? "Excellent" : s >= 60 ? "Bien" : "À améliorer";
  const answered = Object.keys(reponses).length;
  const total = quiz?.questions?.length || 0;

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">📚 ARK Formateur DDA</h2>
          <p className="text-sm text-gray-400 mt-1">Formation continue · Quiz réglementaire · Certification COURTIA</p>
        </div>
        {!quiz && (
          <button onClick={() => startQuiz()} className="bg-purple-600 hover:bg-purple-500 text-white font-medium px-4 py-2 rounded-lg text-sm transition">
            🎯 Lancer un quiz
          </button>
        )}
      </div>

      {/* Score actuel */}
      {dashboard && !quiz && !resultat && (
        <div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-gradient-to-br from-purple-900/40 to-cyan-900/30 rounded-xl p-4 border border-purple-700/40 col-span-2 text-center">
              <p className="text-xs text-gray-400 mb-1">Score DDA actuel</p>
              <p className={`text-5xl font-bold ${scoreColor(dashboard.score_actuel)}`}>{dashboard.score_actuel}</p>
              <p className={`text-sm ${scoreColor(dashboard.score_actuel)}`}>{scoreLabel(dashboard.score_actuel)}</p>
              {dashboard.certification_expiry && (
                <p className="text-xs text-gray-500 mt-2">Certification valable jusqu'au {new Date(dashboard.certification_expiry).toLocaleDateString('fr-FR')}</p>
              )}
            </div>
            <div className="col-span-2 grid grid-cols-2 gap-3">
              {dashboard.sessions_recentes?.slice(0,2).map((s, i) => (
                <div key={i} className="bg-gray-800/60 rounded-xl p-3 border border-gray-700">
                  <p className="text-xs text-gray-400">{new Date(s.completed_at).toLocaleDateString('fr-FR')}</p>
                  <p className={`text-2xl font-bold ${scoreColor(s.score)}`}>{s.score}%</p>
                  <p className="text-xs text-gray-400">{s.nb_questions} questions · {Math.round(s.duree_secondes/60)}min</p>
                </div>
              ))}
            </div>
          </div>

          {/* Tips */}
          {tips?.tips && (
            <div className="bg-purple-900/20 border border-purple-700/30 rounded-xl p-4 mt-4">
              <p className="text-xs text-purple-400 uppercase tracking-wide mb-2">💡 ARK te conseille</p>
              {tips.tips.map((t, i) => <p key={i} className="text-sm text-gray-300 mb-1">{i+1}. {t}</p>)}
            </div>
          )}

          {/* Quiz par catégorie */}
          <div className="mt-4">
            <p className="text-xs text-gray-400 uppercase tracking-wide mb-3">S'entraîner par thème</p>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
              {["devoir_conseil","conformite","iard","sante","prevoyance"].map(cat => {
                const prog = dashboard.progression_par_categorie?.find(p => p.categorie === cat);
                return (
                  <button key={cat} onClick={() => startQuiz(cat)}
                    className="bg-gray-800/40 hover:bg-gray-700/60 rounded-xl border border-gray-700/50 p-3 text-left transition">
                    <p className="text-lg">{CAT_ICONS[cat]}</p>
                    <p className="text-xs font-medium text-white capitalize mt-1">{cat.replace(/_/g,' ')}</p>
                    {prog && <p className={`text-xs mt-0.5 ${scoreColor(parseFloat(prog.taux_reussite))}`}>{Math.round(parseFloat(prog.taux_reussite))}% réussite</p>}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* Quiz en cours */}
      {quiz && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <p className="text-sm text-gray-400">{answered}/{total} réponses</p>
            <div className="flex-1 mx-4 bg-gray-700 rounded-full h-1.5">
              <div className="bg-purple-400 h-1.5 rounded-full transition-all" style={{ width: `${(answered/total)*100}%` }} />
            </div>
            <button onClick={() => setQuiz(null)} className="text-xs text-gray-500 hover:text-gray-300">Quitter</button>
          </div>

          {quiz.questions.map((q, i) => (
            <div key={q.id} className="bg-gray-800/40 rounded-xl border border-gray-700/50 p-4">
              <p className="text-xs text-purple-400 mb-1">{CAT_ICONS[q.categorie]} Question {i+1}</p>
              <p className="text-sm font-medium text-white mb-3">{q.question}</p>
              <div className="grid grid-cols-1 gap-2">
                {(typeof q.options === 'string' ? JSON.parse(q.options) : q.options).map((opt, j) => (
                  <button key={j} onClick={() => setReponses(r => ({...r, [q.id]: j}))}
                    className={`text-left text-sm px-4 py-2.5 rounded-lg border transition ${
                      reponses[q.id] === j
                        ? 'border-purple-500 bg-purple-900/30 text-white'
                        : 'border-gray-600 text-gray-300 hover:border-gray-500 hover:bg-gray-700/30'
                    }`}>
                    <span className="text-gray-500 mr-2">{String.fromCharCode(65+j)}.</span>{opt}
                  </button>
                ))}
              </div>
            </div>
          ))}

          <button onClick={submitQuiz} disabled={answered < total}
            className="w-full py-3 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-medium transition disabled:opacity-40">
            {answered < total ? `Répondez à toutes les questions (${total-answered} restantes)` : "Valider le quiz →"}
          </button>
        </div>
      )}

      {/* Résultat */}
      {resultat && (
        <div className="space-y-4">
          <div className={`rounded-2xl p-6 text-center border ${resultat.score >= 80 ? 'bg-green-900/20 border-green-700/40' : resultat.score >= 60 ? 'bg-amber-900/20 border-amber-700/40' : 'bg-red-900/20 border-red-700/40'}`}>
            <p className={`text-6xl font-bold ${scoreColor(resultat.score)}`}>{resultat.score}%</p>
            <p className="text-white font-medium mt-2">{scoreLabel(resultat.score)}</p>
            <p className="text-gray-400 text-sm">{resultat.correct}/{resultat.total} bonnes réponses · {Math.round(resultat.duree/60)} minutes</p>
            {resultat.certification && (
              <div className="mt-4 bg-green-900/30 border border-green-700/40 rounded-xl p-3">
                <p className="text-green-400 font-medium">🏆 Certification DDA obtenue !</p>
                <p className="text-xs text-gray-400 mt-1">Valable 1 an — téléchargeable dans vos certifications</p>
              </div>
            )}
          </div>

          <div className="space-y-2">
            {resultat.corrections?.map((c, i) => (
              <div key={i} className={`rounded-lg p-3 border ${c.correct ? 'border-green-700/40 bg-green-900/10' : 'border-red-700/40 bg-red-900/10'}`}>
                <div className="flex items-center gap-2 mb-1">
                  <span>{c.correct ? '✅' : '❌'}</span>
                  <span className="text-xs text-gray-400">{CAT_ICONS[c.categorie]}</span>
                </div>
                {!c.correct && c.explication && (
                  <p className="text-xs text-gray-300 ml-6">{c.explication}</p>
                )}
              </div>
            ))}
          </div>

          <div className="flex gap-3">
            <button onClick={() => setResultat(null)} className="flex-1 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">
              Retour
            </button>
            <button onClick={() => startQuiz()} className="flex-1 py-2 rounded-lg bg-purple-600 text-white text-sm font-medium">
              Refaire un quiz
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const ROLES = { admin: "Admin", agent: "Agent", stagiaire: "Stagiaire" };
const ROLE_COLORS = { admin: "text-purple-400", agent: "text-cyan-400", stagiaire: "text-gray-400" };

export default function EquipeCabinet() {
  const [membres, setMembres] = useState([]);
  const [stats, setStats] = useState(null);
  const [showInvite, setShowInvite] = useState(false);
  const [form, setForm] = useState({ email: "", role: "agent" });
  const [invited, setInvited] = useState(null);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  const load = () => {
    fetch(`${API}/api/equipe`, { headers }).then(r => r.json()).then(setMembres);
    fetch(`${API}/api/equipe/stats`, { headers }).then(r => r.json()).then(setStats);
  };
  useEffect(() => { load(); }, []);

  async function inviter() {
    const res = await fetch(`${API}/api/equipe/inviter`, { method: "POST", headers, body: JSON.stringify(form) });
    const data = await res.json();
    setInvited(data);
    setShowInvite(false);
    load();
  }

  async function retirerMembre(membreId) {
    if (!confirm("Retirer ce membre de l'équipe ?")) return;
    await fetch(`${API}/api/equipe/membres/${membreId}`, { method: "DELETE", headers });
    load();
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">👥 Équipe Cabinet</h2>
          <p className="text-sm text-gray-400 mt-1">Gérez votre équipe et les accès au portefeuille</p>
        </div>
        <button onClick={() => setShowInvite(true)} className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-2 rounded-lg text-sm transition">
          + Inviter un collaborateur
        </button>
      </div>

      {invited && (
        <div className="bg-green-900/20 border border-green-700/40 rounded-xl p-4">
          <p className="text-green-400 font-medium text-sm">✅ Invitation envoyée</p>
          <p className="text-xs text-gray-400 mt-1">Lien d'invitation : {invited.invite_url}</p>
          <button onClick={() => navigator.clipboard.writeText(invited.invite_url)} className="text-xs text-cyan-400 mt-1 hover:text-cyan-300">Copier le lien</button>
        </div>
      )}

      {stats && (
        <div className="grid grid-cols-3 gap-4">
          {[
            { label: "Collaborateurs", val: stats.nb_membres || 0 },
            { label: "Clients équipe", val: stats.total_clients || 0 },
            { label: "CA équipe", val: `${Math.round(parseFloat(stats.ca_total_equipe||0)).toLocaleString('fr-FR')} €` },
          ].map(s => (
            <div key={s.label} className="bg-gray-800/60 rounded-xl p-4 border border-gray-700 text-center">
              <p className="text-xl font-bold text-white">{s.val}</p>
              <p className="text-xs text-gray-400 mt-1">{s.label}</p>
            </div>
          ))}
        </div>
      )}

      <div className="space-y-3">
        {membres.length === 0 && (
          <div className="text-center py-12 text-gray-500">
            <p className="text-4xl mb-3">👥</p>
            <p className="text-sm">Aucun collaborateur pour l'instant.</p>
          </div>
        )}
        {membres.map(m => (
          <div key={m.id} className="bg-gray-800/40 rounded-xl border border-gray-700/50 p-4">
            <div className="flex justify-between items-start">
              <div>
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 rounded-full bg-gray-700 flex items-center justify-center text-sm font-medium text-white">
                    {(m.nom_cabinet || m.email)?.[0]?.toUpperCase()}
                  </div>
                  <div>
                    <p className="text-sm font-medium text-white">{m.nom_cabinet || m.email}</p>
                    <p className="text-xs text-gray-400">{m.email}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3 mt-2">
                  <span className={`text-xs font-medium ${ROLE_COLORS[m.role]}`}>{ROLES[m.role] || m.role}</span>
                  <span className="text-gray-600">·</span>
                  <span className="text-xs text-gray-500">{m.nb_clients_assignes || 0} clients assignés</span>
                  <span className="text-gray-600">·</span>
                  <span className="text-xs text-gray-500">{Math.round(parseFloat(m.ca_gere||0)).toLocaleString('fr-FR')} € CA</span>
                </div>
              </div>
              <div className="flex gap-2">
                <select value={m.role}
                  onChange={async e => {
                    await fetch(`${API}/api/equipe/membres/${m.membre_user_id}/role`, {
                      method: "PATCH", headers, body: JSON.stringify({ role: e.target.value })
                    });
                    load();
                  }}
                  className="text-xs bg-gray-700 border border-gray-600 rounded px-2 py-1 text-gray-300">
                  {Object.entries(ROLES).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                </select>
                <button onClick={() => retirerMembre(m.membre_user_id)}
                  className="text-xs text-red-400 hover:text-red-300 px-2 py-1 border border-red-900/40 rounded">
                  Retirer
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showInvite && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-2xl p-6 w-full max-w-md border border-gray-700 space-y-4">
            <h3 className="text-lg font-semibold text-white">Inviter un collaborateur</h3>
            <input placeholder="Email du collaborateur" type="email" value={form.email}
              onChange={e => setForm(f => ({...f, email: e.target.value}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            <select value={form.role} onChange={e => setForm(f => ({...f, role: e.target.value}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white">
              {Object.entries(ROLES).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </select>
            <div className="flex gap-3">
              <button onClick={() => setShowInvite(false)} className="flex-1 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">Annuler</button>
              <button onClick={inviter} className="flex-1 py-2 rounded-lg bg-cyan-500 text-black font-medium text-sm">Envoyer l'invitation</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { Bell, AlertCircle, Info, Check } from 'lucide-react'
import api from '../api'

const POLL_INTERVAL_MS = 60_000

export default function NotificationBell() {
  const [showPanel, setShowPanel] = useState(false)
  const [alerts, setAlerts] = useState([])
  const [unread, setUnread] = useState(0)
  const [loading, setLoading] = useState(false)
  const pollRef = useRef(null)

  const loadNotifications = useCallback(async (silent = false) => {
    if (!silent) setLoading(true)
    try {
      const res = await api.get('/notifications?limit=12')
      setAlerts(Array.isArray(res?.data?.rows) ? res.data.rows : [])
      setUnread(Number(res?.data?.unread || 0))
    } catch {
      if (!silent) {
        setAlerts([])
        setUnread(0)
      }
    } finally {
      if (!silent) setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadNotifications(true)
    pollRef.current = setInterval(() => loadNotifications(true), POLL_INTERVAL_MS)
    return () => { if (pollRef.current) clearInterval(pollRef.current) }
  }, [loadNotifications])

  async function markAllRead() {
    try {
      await api.post('/notifications/read-all')
      await loadNotifications()
    } catch {
      // Non bloquant: le panneau restera consultable.
    }
  }

  return (
    <div className="relative">
      <button
        onClick={() => {
          setShowPanel(!showPanel)
          if (!showPanel) loadNotifications()
        }}
        className="relative rounded-xl border border-white/10 bg-white/[0.06] p-2 text-white shadow-lg shadow-black/20 backdrop-blur-xl transition hover:bg-white/[0.1]"
        aria-label="Notifications"
      >
        <Bell size={18} />
        {unread > 0 && (
          <span className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-rose-500 px-1 text-[10px] font-bold text-white">
            {unread}
          </span>
        )}
      </button>

      {showPanel && (
        <div className="absolute right-0 top-12 z-50 max-h-96 w-80 overflow-y-auto rounded-2xl border border-white/12 bg-[#090b1d]/95 p-4 shadow-2xl shadow-black/40 backdrop-blur-2xl">
          <div className="mb-4 flex items-center justify-between gap-3">
            <div>
              <h3 className="text-sm font-bold text-white">Notifications</h3>
              <p className="text-[11px] text-white/45">{unread} non lue{unread > 1 ? 's' : ''}</p>
            </div>
            {unread > 0 && (
              <button onClick={markAllRead} className="inline-flex items-center gap-1 rounded-full border border-white/10 bg-white/5 px-2 py-1 text-[11px] font-semibold text-white/75 hover:bg-white/10">
                <Check size={12} />
                Tout lu
              </button>
            )}
          </div>
          <div className="space-y-2">
            {loading && <p className="rounded-xl bg-white/5 p-3 text-xs text-white/55">Chargement…</p>}
            {!loading && alerts.length === 0 && (
              <p className="rounded-xl border border-white/10 bg-white/[0.04] p-4 text-center text-xs text-white/55">
                Aucune notification pour le moment. COURTIA fera remonter les échéances, tâches et signaux ARK ici.
              </p>
            )}
            {!loading && alerts.map(alert => {
              const urgent = ['urgent', 'danger', 'error'].includes(String(alert.severity || alert.type).toLowerCase())
              const warning = ['warning', 'warn'].includes(String(alert.severity || alert.type).toLowerCase())
              return (
                <a
                  key={alert.id}
                  href={alert.link || '#'}
                  className={`block rounded-xl border p-3 no-underline ${
                    urgent ? 'border-rose-400/30 bg-rose-500/10' : warning ? 'border-amber-300/30 bg-amber-400/10' : 'border-cyan-300/20 bg-cyan-400/10'
                  }`}
                >
                  <div className="flex items-start gap-2">
                    {urgent || warning ? <AlertCircle size={15} className={urgent ? 'mt-0.5 text-rose-300' : 'mt-0.5 text-amber-200'} /> : <Info size={15} className="mt-0.5 text-cyan-200" />}
                    <div className="min-w-0 flex-1">
                      <p className="text-xs font-semibold text-white">{alert.title}</p>
                      <p className="mt-1 text-[11px] leading-relaxed text-white/58">{alert.body || alert.message || alert.msg}</p>
                      <p className="mt-2 text-[10px] uppercase tracking-[0.12em] text-white/35">{alert.kind || alert.type || 'info'}</p>
                    </div>
                  </div>
                </a>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

