  {
    id: 'pilotage',
    label: 'PILOTAGE',
    glyph: '🎯',
    items: [
      { path: '/dashboard',     label: 'Cockpit',       icon: LayoutDashboard },
      { path: '/morning-brief', label: 'Morning Brief', icon: Sunrise },
