const styles = {
  container: {
    position: 'fixed',
    top: 'var(--aurora-space-4)',
    right: 'var(--aurora-space-4)',
    zIndex: 9999,
    display: 'flex',
    flexDirection: 'column',
    gap: 'var(--aurora-space-2)',
