    const fd = new FormData();
    fd.append('file', file);
    try {
      const r = await fetch(`${apiBase}/bordereau/upload`, {
        method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` }, body: fd
      });
      const result = await r.json();
      if (result.success) {
        alert(`Bordereau traité :\n${result.total_lignes} lignes\n${result.lignes_rapprochees} rapprochées\n${result.lignes_non_rapprochees} non rapprochées\nÉcart total : ${result.ecart_total?.toFixed(2)}€`);
        await load();
      } else alert(`Erreur : ${result.error}`);
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const generateRelance = async (ecartId) => {
    const r = await fetch(`${apiBase}/bordereau/ecart/${ecartId}/relance`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } });
    const d = await r.json();
    if (d.success) setSelectedEcart({ ...d.draft, ecart_id: ecartId });
  };

  const markRecovered = async (ecartId, amount) => {
    await fetch(`${apiBase}/bordereau/ecart/${ecartId}/recovered`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${authToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount })
    });
    setSelectedEcart(null);
    await load();
  };

  if (loading || !data) return <div className="rounded-3xl bg-slate-900/60 border border-slate-700/50 p-12 flex items-center justify-center"><Loader2 className="w-6 h-6 text-cyan-400 animate-spin" /></div>;

  return (
    <div className="space-y-5">
      <div className="rounded-3xl bg-gradient-to-br from-slate-900/80 to-slate-950/90 border border-cyan-500/20 backdrop-blur-xl p-6">
        <div className="flex items-center justify-between gap-4 flex-wrap mb-5">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-cyan-400 to-purple-500 flex items-center justify-center">
              <TrendingUp className="w-6 h-6 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-semibold text-white">Bordereau Intelligence</h2>
              <p className="text-xs text-slate-400">Commissions oubliées récupérées automatiquement</p>
            </div>
          </div>
          <input ref={fileInputRef} type="file" accept=".pdf,.xls,.xlsx,.csv" onChange={handleUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} disabled={uploading} className="px-4 py-2.5 rounded-xl bg-gradient-to-r from-cyan-500 to-purple-500 text-white text-sm font-medium hover:opacity-90 disabled:opacity-50 flex items-center gap-2">
            {uploading ? <><Loader2 className="w-4 h-4 animate-spin" /> Analyse…</> : <><Upload className="w-4 h-4" /> Uploader un bordereau</>}
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <Stat label="Écarts ouverts" value={data.ecarts_ouverts.length} color="amber" />
          <Stat label="À récupérer" value={`${Math.round(data.total_ecarts_ouverts).toLocaleString('fr')}€`} color="red" />
          <Stat label="Récupéré 12 mois" value={`${Math.round(data.total_recovered_12m).toLocaleString('fr')}€`} color="emerald" />
          <Stat label="Bordereaux traités" value={data.bordereaux.length} color="cyan" />
        </div>
      </div>

      <div className="rounded-2xl bg-slate-900/60 border border-slate-700/50 backdrop-blur-xl p-5">
        <h3 className="text-white font-semibold mb-3 flex items-center gap-2">
          <AlertCircle className="w-4 h-4 text-amber-400" /> Écarts à récupérer
        </h3>
        {data.ecarts_ouverts.length === 0 ? (
          <div className="text-slate-400 text-sm text-center py-8">Uploade ton premier bordereau pour voir apparaître les écarts.</div>
        ) : (
          <div className="space-y-2">
            {data.ecarts_ouverts.map(ec => (
              <div key={ec.id} className="rounded-xl bg-slate-800/40 border border-slate-700/50 p-4">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="text-white text-sm font-medium">{ec.description}</div>
                    <div className="text-xs text-slate-400 mt-1">Type : {ec.type_ecart} · {ec.relance_envoyee_at ? `Relancé le ${new Date(ec.relance_envoyee_at).toLocaleDateString('fr')}` : 'Non relancé'}</div>
                  </div>
                  <div className="text-xl font-bold text-amber-300">{parseFloat(ec.montant_ecart).toFixed(2)}€</div>
                </div>
                <div className="flex gap-2 mt-3">
                  <button onClick={() => generateRelance(ec.id)} className="px-3 py-1.5 rounded-lg bg-cyan-500/20 border border-cyan-500/40 text-cyan-200 text-xs flex items-center gap-1.5">
                    <Mail className="w-3.5 h-3.5" /> Générer relance
                  </button>
                  <button onClick={() => { const a = prompt('Montant récupéré (€) :', ec.montant_ecart); if (a) markRecovered(ec.id, parseFloat(a)); }} className="px-3 py-1.5 rounded-lg bg-emerald-500/20 border border-emerald-500/40 text-emerald-200 text-xs flex items-center gap-1.5">
                    <Check className="w-3.5 h-3.5" /> Récupéré
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {selectedEcart && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4" onClick={() => setSelectedEcart(null)}>
          <div className="rounded-2xl bg-slate-900 border border-slate-700 max-w-2xl w-full p-6" onClick={e => e.stopPropagation()}>
            <h3 className="text-white font-semibold mb-3">Brouillon relance compagnie</h3>
            <div className="rounded-xl bg-slate-800 border border-slate-700 p-4 mb-4">
              <div className="text-xs text-slate-400 mb-1">Sujet</div>
              <div className="text-white text-sm font-medium mb-3">{selectedEcart.subject}</div>
              <div className="text-xs text-slate-400 mb-1">Message</div>
              <pre className="text-slate-200 text-sm whitespace-pre-wrap font-sans">{selectedEcart.body}</pre>
            </div>
            <div className="flex gap-2">
              <button onClick={() => { navigator.clipboard.writeText(`${selectedEcart.subject}\n\n${selectedEcart.body}`); alert('Copié'); }} className="flex-1 px-4 py-2.5 rounded-xl bg-cyan-500 text-white font-medium">Copier</button>
              <button onClick={() => window.location.href = `mailto:?subject=${encodeURIComponent(selectedEcart.subject)}&body=${encodeURIComponent(selectedEcart.body)}`} className="flex-1 px-4 py-2.5 rounded-xl bg-gradient-to-r from-cyan-500 to-purple-500 text-white font-medium">Ouvrir Mail</button>
              <button onClick={() => setSelectedEcart(null)} className="px-4 py-2.5 rounded-xl bg-slate-800 text-slate-300 border border-slate-700">Fermer</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Stat({ label, value, color }) {
  const map = { white: 'text-white', emerald: 'text-emerald-300', amber: 'text-amber-300', red: 'text-red-300', cyan: 'text-cyan-300' };
  return (
    <div className="rounded-xl bg-slate-800/40 border border-slate-700/30 p-3">
      <div className="text-[10px] uppercase tracking-wider text-slate-400">{label}</div>
      <div className={`text-2xl font-bold mt-1 ${map[color]}`}>{value}</div>
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const PACKS = {
  pack500: { credits: 500, prix: "60 € HT", label: "Pack 500" },
  pack1000: { credits: 1000, prix: "110 € HT", label: "Pack 1 000" },
  pack5000: { credits: 5000, prix: "450 € HT", label: "Pack 5 000" }
};

export default function CampagnesSMS() {
  const [data, setData] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ nom: "", message: "" });
  const [sending, setSending] = useState(null);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  const load = () => fetch(`${API}/api/sms/dashboard`, { headers }).then(r => r.json()).then(setData);
  useEffect(() => { load(); }, []);

  const chars = form.message.length;
  const smsCount = Math.ceil(chars / 160) || 1;

  async function createCampagne() {
    await fetch(`${API}/api/sms/campagne`, { method: "POST", headers, body: JSON.stringify(form) });
    setShowForm(false);
    load();
  }

  async function sendCampagne(id) {
    setSending(id);
    const res = await fetch(`${API}/api/sms/campagne/${id}/send`, { method: "POST", headers });
    const result = await res.json();
    setSending(null);
    if (result.error) { alert(`❌ ${result.error}`); return; }
    alert(`✅ ${result.envoyes} SMS envoyés · Coût : ${result.cout_facture?.toFixed(2)} €`);
    load();
  }

  async function buyPack(pack) {
    if (!confirm(`Acheter le ${PACKS[pack].label} pour ${PACKS[pack].prix} ?`)) return;
    await fetch(`${API}/api/sms/buy-pack`, { method: "POST", headers, body: JSON.stringify({ pack }) });
    load();
  }

  if (!data) return <div className="p-6 text-gray-400">Chargement...</div>;

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">📱 Campagnes SMS</h2>
          <p className="text-sm text-gray-400 mt-1">0,15 €/SMS · Marge gérée par COURTIA</p>
        </div>
        <button onClick={() => setShowForm(true)} className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-2 rounded-lg text-sm transition">
          + Nouvelle campagne
        </button>
      </div>

      {/* Crédits + packs */}
      <div className="bg-gray-800/60 rounded-xl p-4 border border-gray-700">
        <div className="flex justify-between items-center mb-3">
          <span className="text-gray-300 text-sm">Crédits SMS disponibles</span>
          <span className="text-2xl font-bold text-cyan-400">{data.credits?.credits || 0}</span>
        </div>
        <div className="grid grid-cols-3 gap-2">
          {Object.entries(PACKS).map(([key, p]) => (
            <button key={key} onClick={() => buyPack(key)}
              className="bg-gray-700 hover:bg-gray-600 rounded-lg p-3 text-center transition">
              <p className="text-white font-medium text-sm">{p.label}</p>
              <p className="text-gray-400 text-xs">{p.prix}</p>
            </button>
          ))}
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4">
        {[
          { label: "SMS envoyés", val: data.stats?.total_envoyes || 0 },
          { label: "Campagnes", val: data.stats?.nb_campagnes || 0 },
          { label: "Total dépensé", val: `${parseFloat(data.stats?.total_depense || 0).toFixed(2)} €` },
        ].map(s => (
          <div key={s.label} className="bg-gray-800/60 rounded-xl p-4 border border-gray-700 text-center">
            <p className="text-xl font-bold text-white">{s.val}</p>
            <p className="text-xs text-gray-400 mt-1">{s.label}</p>
          </div>
        ))}
      </div>

      {/* Campagnes */}
      <div className="space-y-2">
        {data.campagnes?.map(c => (
          <div key={c.id} className="bg-gray-800/40 rounded-lg p-3 flex justify-between items-center border border-gray-700/50">
            <div>
              <p className="text-sm font-medium text-white">{c.nom}</p>
              <p className="text-xs text-gray-400">{c.nb_destinataires} destinataires · {new Date(c.created_at).toLocaleDateString("fr-FR")}</p>
              {c.statut === "sent" && <p className="text-xs text-green-400">{c.nb_envoyes} envoyés · {parseFloat(c.cout_total_facture).toFixed(2)} €</p>}
            </div>
            <div className="flex items-center gap-2">
              <span className={`text-xs px-2 py-1 rounded-full ${c.statut === "sent" ? "bg-green-900/50 text-green-400" : "bg-gray-700 text-gray-300"}`}>
                {c.statut === "sent" ? "Envoyée" : "Brouillon"}
              </span>
              {c.statut === "brouillon" && (
                <button onClick={() => sendCampagne(c.id)} disabled={sending === c.id}
                  className="text-xs bg-cyan-500 hover:bg-cyan-400 text-black px-3 py-1 rounded-lg transition disabled:opacity-50">
                  {sending === c.id ? "..." : "Envoyer"}
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-2xl p-6 w-full max-w-md border border-gray-700 space-y-4">
            <h3 className="text-lg font-semibold text-white">Nouvelle campagne SMS</h3>
            <input placeholder="Nom de la campagne" value={form.nom}
              onChange={e => setForm(f => ({ ...f, nom: e.target.value }))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            <div>
              <textarea placeholder="Message SMS (variables : {prenom}, {nom})" value={form.message}
                onChange={e => setForm(f => ({ ...f, message: e.target.value }))} rows={4}
                className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white resize-none" />
              <div className="flex justify-between text-xs text-gray-400 mt-1">
                <span>{chars} caractères</span>
                <span>{smsCount} SMS · {(smsCount * 0.15).toFixed(2)} €/destinataire</span>
              </div>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setShowForm(false)} className="flex-1 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">Annuler</button>
              <button onClick={createCampagne} className="flex-1 py-2 rounded-lg bg-cyan-500 text-black font-medium text-sm">Créer</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";

function ScoreBar({ label, score }) {
  const color = score >= 75 ? "bg-green-500" : score >= 50 ? "bg-amber-400" : "bg-red-500";
  return (
    <div className="space-y-1">
      <div className="flex justify-between text-xs">
        <span className="text-gray-300">{label}</span>
        <span className={score >= 75 ? "text-green-400" : score >= 50 ? "text-amber-400" : "text-red-400"}>{score}/100</span>
      </div>
      <div className="w-full bg-gray-700 rounded-full h-1.5">
        <div className={`${color} h-1.5 rounded-full transition-all`} style={{ width: `${score}%` }} />
      </div>
    </div>
  );
}

export default function ArkCoachDashboard() {
  const [data, setData] = useState(null);
  const [tips, setTips] = useState(null);
  const [selected, setSelected] = useState(null);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}` };

  useEffect(() => {
    fetch(`${API}/api/ark-coach/progression`, { headers }).then(r => r.json()).then(setData);
    fetch(`${API}/api/ark-coach/tips`, { headers }).then(r => r.json()).then(setTips);
  }, []);

  if (!data) return <div className="p-6 text-gray-400">Chargement...</div>;

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-xl font-semibold text-white">🎯 ARK Coach Commercial</h2>
        <p className="text-sm text-gray-400 mt-1">Analyse de tes appels · Score + coaching personnalisé</p>
      </div>

      {/* Tips du moment */}
      {tips?.tips && (
        <div className="bg-gradient-to-r from-purple-900/40 to-cyan-900/30 rounded-xl p-4 border border-purple-700/40">
          <p className="text-xs text-purple-300 uppercase tracking-wide mb-2">💡 Tips ARK cette semaine</p>
          <ul className="space-y-1">
            {tips.tips.map((t, i) => (
              <li key={i} className="text-sm text-gray-200 flex gap-2"><span className="text-purple-400">→</span>{t}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Derniers coachings */}
      <div className="space-y-3">
        <p className="text-xs text-gray-400 uppercase tracking-wide">Derniers appels analysés</p>
        {data.derniers_coachings?.length === 0 && (
          <p className="text-gray-500 text-sm text-center py-8">Aucun appel analysé pour l'instant.<br/>Les appels ARK Voice sont analysés automatiquement.</p>
        )}
        {data.derniers_coachings?.map(c => (
          <div key={c.id} onClick={() => setSelected(selected?.id === c.id ? null : c)}
            className="bg-gray-800/40 rounded-xl border border-gray-700/50 p-4 cursor-pointer hover:border-gray-600 transition">
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm font-medium text-white">Appel #{c.call_id || c.id}</p>
                <p className="text-xs text-gray-400">{new Date(c.analysed_at).toLocaleDateString("fr-FR")}</p>
              </div>
              <div className="text-right">
                <span className={`text-2xl font-bold ${c.score_global >= 75 ? "text-green-400" : c.score_global >= 50 ? "text-amber-400" : "text-red-400"}`}>
                  {c.score_global}
                </span>
                <span className="text-gray-500 text-xs">/100</span>
              </div>
            </div>

            {selected?.id === c.id && (
              <div className="mt-4 space-y-4 border-t border-gray-700 pt-4">
                <div className="space-y-2">
                  <ScoreBar label="Accroche" score={c.score_accroche} />
                  <ScoreBar label="Découverte" score={c.score_decouverte} />
                  <ScoreBar label="Argumentation" score={c.score_argumentation} />
                  <ScoreBar label="Closing" score={c.score_closing} />
                </div>
                {c.points_forts && (
                  <div>
                    <p className="text-xs text-green-400 mb-1">✅ Points forts</p>
                    {(typeof c.points_forts === 'string' ? JSON.parse(c.points_forts) : c.points_forts).map((p, i) => (
                      <p key={i} className="text-xs text-gray-300">· {p}</p>
                    ))}
                  </div>
                )}
                {c.axes_amelioration && (
                  <div>
                    <p className="text-xs text-amber-400 mb-1">⚠️ Axes d'amélioration</p>
                    {(typeof c.axes_amelioration === 'string' ? JSON.parse(c.axes_amelioration) : c.axes_amelioration).map((a, i) => (
                      <p key={i} className="text-xs text-gray-300">· {a}</p>
                    ))}
                  </div>
                )}
                {c.next_actions && (
                  <div>
                    <p className="text-xs text-cyan-400 mb-1">🎯 Actions</p>
                    {(typeof c.next_actions === 'string' ? JSON.parse(c.next_actions) : c.next_actions).map((a, i) => (
                      <p key={i} className="text-xs text-gray-300">· {a}</p>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

