          </div>
        </div>

        {/* Alert critique */}
        {brief.alert && (
          <div className="mb-6 rounded-2xl bg-gradient-to-r from-red-500/10 to-orange-500/10 border border-red-500/40 p-4 flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-red-400 mt-0.5 flex-shrink-0" />
            <p className="text-red-100 text-sm">{brief.alert}</p>
          </div>
        )}

        {/* Actions list */}
        <div className="space-y-3">
          {(brief.actions || []).map((action, i) => {
            const style = PRIORITY_STYLES[action.priority] || PRIORITY_STYLES[3];
            const Icon = TYPE_ICONS[action.type] || CheckCircle2;
            const isDone = completed.has(i);

            return (
              <div
                key={i}
                className={`relative overflow-hidden rounded-2xl bg-gradient-to-r ${style.bg} border ${style.border} backdrop-blur-sm p-4 md:p-5 transition-all ${isDone ? 'opacity-50' : 'hover:scale-[1.01]'}`}
              >
                <div className="flex items-start gap-4">
                  <div className="w-10 h-10 rounded-xl bg-slate-900/60 flex items-center justify-center flex-shrink-0">
                    <Icon className="w-5 h-5 text-white" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1 flex-wrap">
                      <span className="text-[10px] uppercase font-semibold tracking-wider text-slate-300 px-2 py-0.5 rounded bg-slate-900/40">
                        {style.label}
                      </span>
                      <span className="text-slate-400 text-xs">~{action.estimated_minutes}min</span>
                      {action.expected_value > 0 && (
                        <span className="text-cyan-300 text-xs font-medium">+{action.expected_value.toLocaleString('fr')}€</span>
                      )}
                    </div>
                    <div className="text-white font-semibold">{action.action}</div>
                    <div className="text-slate-300 text-sm mt-0.5">{action.client_name}</div>
                    <div className="text-slate-400 text-xs mt-1.5 italic">{action.reason}</div>

                    {action.draft_message && (
                      <details className="mt-3">
                        <summary className="text-xs text-cyan-400 cursor-pointer hover:text-cyan-300">Voir le message IA →</summary>
                        <div className="mt-2 p-3 rounded-lg bg-slate-900/60 border border-slate-700/50 text-slate-200 text-sm whitespace-pre-wrap">
                          {action.draft_message}
                        </div>
                      </details>
                    )}
                  </div>
                  <button
                    onClick={() => markDone(i)}
                    disabled={isDone}
                    className={`flex-shrink-0 w-9 h-9 rounded-full border transition ${isDone ? 'bg-emerald-500/20 border-emerald-500/40 text-emerald-300' : 'bg-slate-800/60 border-slate-700/50 text-slate-400 hover:text-emerald-300 hover:border-emerald-500/40'}`}
                  >
                    <CheckCircle2 className="w-5 h-5 mx-auto" />
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {(!brief.actions || brief.actions.length === 0) && (
          <div className="text-center py-12 text-slate-400">
            <Sparkles className="w-10 h-10 mx-auto mb-3 opacity-40" />
            <p>Journée calme — bon moment pour prospecter.</p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const JOURS = ["Dim","Lun","Mar","Mer","Jeu","Ven","Sam"];
const TYPE_COLORS = { appel: "bg-blue-900/50 text-blue-300", visio: "bg-purple-900/50 text-purple-300", presentiel: "bg-green-900/50 text-green-300", client_entrant: "bg-amber-900/50 text-amber-300" };

export default function AgendaRDV() {
  const [rdvs, setRdvs] = useState([]);
  const [view, setView] = useState("semaine");
  const [showForm, setShowForm] = useState(false);
  const [showDispo, setShowDispo] = useState(false);
  const [bookingPage, setBookingPage] = useState(null);
  const [form, setForm] = useState({ titre: "", clientId: "", dateHeure: "", dureeMinutes: 60, typeRdv: "appel", lienVisio: "", clientEmail: "", sendConfirmation: true });
  const [dispos, setDispos] = useState([]);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  const now = new Date();
  const debut = new Date(now); debut.setDate(now.getDate() - now.getDay());
  const fin = new Date(debut); fin.setDate(debut.getDate() + 6);

  useEffect(() => {
    fetch(`${API}/api/agenda?debut=${debut.toISOString()}&fin=${fin.toISOString()}`, { headers })
      .then(r => r.json()).then(setRdvs);
    fetch(`${API}/api/agenda/disponibilites`, { headers }).then(r => r.json()).then(setDispos);
  }, []);

  async function createRDV() {
    await fetch(`${API}/api/agenda/rdv`, { method: "POST", headers, body: JSON.stringify(form) });
    setShowForm(false);
    fetch(`${API}/api/agenda?debut=${debut.toISOString()}&fin=${fin.toISOString()}`, { headers }).then(r => r.json()).then(setRdvs);
  }

  async function createBookingPage() {
    const slug = prompt("Slug de ta page (ex: dupont-conseils):");
    if (!slug) return;
    const res = await fetch(`${API}/api/agenda/booking-page`, {
      method: "POST", headers, body: JSON.stringify({ slug, titre: "Prendre un RDV", durees: [30, 60] })
    });
    const data = await res.json();
    setBookingPage(data);
  }

  async function updateStatut(id, statut) {
    await fetch(`${API}/api/agenda/rdv/${id}/statut`, { method: "PATCH", headers, body: JSON.stringify({ statut }) });
    setRdvs(prev => prev.map(r => r.id === id ? { ...r, statut } : r));
  }

  const rdvsParJour = JOURS.map((_, i) => {
    const d = new Date(debut); d.setDate(debut.getDate() + i);
    return rdvs.filter(r => new Date(r.date_heure).toDateString() === d.toDateString());
  });

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">📅 Agenda & RDV</h2>
          <p className="text-sm text-gray-400 mt-1">Prise de RDV en ligne + gestion agenda</p>
        </div>
        <div className="flex gap-2">
          <button onClick={createBookingPage} className="border border-gray-600 text-gray-300 hover:bg-gray-800 px-3 py-2 rounded-lg text-sm transition">
            🔗 Page réservation
          </button>
          <button onClick={() => setShowForm(true)} className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-2 rounded-lg text-sm transition">
            + RDV
          </button>
        </div>
      </div>

      {bookingPage && (
        <div className="bg-green-900/20 border border-green-700/40 rounded-xl p-3 flex justify-between items-center">
          <div>
            <p className="text-green-400 text-sm font-medium">✅ Page de réservation créée</p>
            <p className="text-gray-400 text-xs mt-0.5">{bookingPage.lien_public}</p>
          </div>
          <button onClick={() => { navigator.clipboard.writeText(bookingPage.lien_public); }}
            className="text-xs text-cyan-400 hover:text-cyan-300">Copier</button>
        </div>
      )}

      {/* Semaine */}
      <div className="grid grid-cols-7 gap-1">
        {JOURS.map((jour, i) => {
          const d = new Date(debut); d.setDate(debut.getDate() + i);
          const isToday = d.toDateString() === now.toDateString();
          return (
            <div key={i} className={`rounded-xl border ${isToday ? 'border-cyan-500/50 bg-cyan-900/10' : 'border-gray-700/50 bg-gray-800/30'} p-2 min-h-[120px]`}>
              <p className={`text-xs font-medium mb-1 ${isToday ? 'text-cyan-400' : 'text-gray-400'}`}>
                {jour} <span className={isToday ? 'text-cyan-300' : 'text-gray-500'}>{d.getDate()}</span>
              </p>
              {rdvsParJour[i].map(r => (
                <div key={r.id} className={`rounded p-1.5 mb-1 text-xs cursor-pointer ${TYPE_COLORS[r.type_rdv] || 'bg-gray-700 text-gray-300'}`}
                  onClick={() => { if (confirm(`Annuler "${r.titre}" ?`)) updateStatut(r.id, 'annule'); }}>
                  <p className="font-medium truncate">{r.titre}</p>
                  <p className="opacity-70">{new Date(r.date_heure).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}</p>
                  {r.client_nom && <p className="opacity-70 truncate">{r.client_nom}</p>}
                </div>
              ))}
            </div>
          );
        })}
      </div>

      {/* Liste complète */}
      <div className="space-y-2">
        <p className="text-xs text-gray-400 uppercase tracking-wide">Cette semaine</p>
        {rdvs.length === 0 && <p className="text-gray-500 text-sm text-center py-6">Aucun RDV cette semaine</p>}
        {rdvs.sort((a,b) => new Date(a.date_heure)-new Date(b.date_heure)).map(r => (
          <div key={r.id} className="bg-gray-800/40 rounded-lg p-3 flex justify-between items-center border border-gray-700/50">
            <div>
              <p className="text-sm font-medium text-white">{r.titre}</p>
              <p className="text-xs text-gray-400">
                {new Date(r.date_heure).toLocaleDateString('fr-FR', { weekday:'long', day:'numeric', month:'long' })} à {new Date(r.date_heure).toLocaleTimeString('fr-FR', { hour:'2-digit', minute:'2-digit' })} · {r.duree_minutes} min
              </p>
              {r.client_nom && <p className="text-xs text-gray-500">{r.client_nom}</p>}
            </div>
            <div className="flex items-center gap-2">
              <span className={`text-xs px-2 py-0.5 rounded-full ${TYPE_COLORS[r.type_rdv]}`}>{r.type_rdv}</span>
              {r.lien_visio && <a href={r.lien_visio} target="_blank" className="text-xs text-cyan-400">📹 Rejoindre</a>}
            </div>
          </div>
        ))}
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-2xl p-6 w-full max-w-md border border-gray-700 space-y-3">
            <h3 className="text-lg font-semibold text-white">Nouveau RDV</h3>
            <input placeholder="Titre" value={form.titre} onChange={e => setForm(f => ({...f, titre: e.target.value}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            <input type="datetime-local" value={form.dateHeure} onChange={e => setForm(f => ({...f, dateHeure: e.target.value}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            <div className="grid grid-cols-2 gap-2">
              <select value={form.dureeMinutes} onChange={e => setForm(f => ({...f, dureeMinutes: parseInt(e.target.value)}))}
                className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white">
                {[15,30,45,60,90,120].map(d => <option key={d} value={d}>{d} min</option>)}
              </select>
              <select value={form.typeRdv} onChange={e => setForm(f => ({...f, typeRdv: e.target.value}))}
                className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white">
                {['appel','visio','presentiel'].map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            {form.typeRdv === 'visio' && (
              <input placeholder="Lien visio (Meet, Teams...)" value={form.lienVisio} onChange={e => setForm(f => ({...f, lienVisio: e.target.value}))}
                className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            )}
            <input placeholder="Email client (pour confirmation)" value={form.clientEmail} onChange={e => setForm(f => ({...f, clientEmail: e.target.value}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            <div className="flex gap-3 pt-2">
              <button onClick={() => setShowForm(false)} className="flex-1 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">Annuler</button>
              <button onClick={createRDV} className="flex-1 py-2 rounded-lg bg-cyan-500 text-black font-medium text-sm">Créer</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";
const PRODUITS = ["auto","habitation","sante","prevoyance","emprunteur","pme","rc_pro","cyber"];

export default function ComparateurDevis() {
  const [dashboard, setDashboard] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [resultats, setResultats] = useState(null);
  const [form, setForm] = useState({ clientId: "", typeProduit: "habitation", besoins: {} });
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  useEffect(() => {
    fetch(`${API}/api/devis/dashboard`, { headers }).then(r => r.json()).then(setDashboard);
  }, []);

  async function comparer() {
    setLoading(true);
    const res = await fetch(`${API}/api/devis/comparer`, { method: "POST", headers, body: JSON.stringify(form) });
    const data = await res.json();
    setLoading(false);
    setResultats(data);
    setShowForm(false);
  }

  async function selectOffre(devisId, index) {
    await fetch(`${API}/api/devis/${devisId}/select`, { method: "POST", headers, body: JSON.stringify({ offreIndex: index }) });
    alert("✅ Offre sélectionnée. Tu peux maintenant envoyer la signature électronique.");
    setResultats(null);
    fetch(`${API}/api/devis/dashboard`, { headers }).then(r => r.json()).then(setDashboard);
  }

  const stats = dashboard?.stats;

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">⚡ Comparateur Devis IA</h2>
          <p className="text-sm text-gray-400 mt-1">3 offres en 30 secondes · Commission sur contrat signé</p>
        </div>
        <button onClick={() => setShowForm(true)} className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-2 rounded-lg text-sm transition">
          + Nouveau devis
        </button>
      </div>

      {stats && (
        <div className="grid grid-cols-3 gap-4">
          {[
            { label: "Devis générés", val: stats.total_devis || 0, color: "text-white" },
            { label: "Contrats signés", val: stats.contrats_signes || 0, color: "text-green-400" },
            { label: "Commissions", val: `${parseFloat(stats.commissions_totales || 0).toFixed(0)} €`, color: "text-amber-400" },
          ].map(s => (
            <div key={s.label} className="bg-gray-800/60 rounded-xl p-4 border border-gray-700 text-center">
              <p className={`text-xl font-bold ${s.color}`}>{s.val}</p>
              <p className="text-xs text-gray-400 mt-1">{s.label}</p>
            </div>
          ))}
        </div>
      )}

      {/* Résultats comparaison */}
      {resultats && (() => {
        const res = typeof resultats.resultats === 'string' ? JSON.parse(resultats.resultats) : resultats.resultats;
        return (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <p className="text-white font-medium">Résultats — {resultats.type_produit}</p>
              {res?.recommandation_ark && (
                <span className="text-xs bg-cyan-900/50 text-cyan-300 px-3 py-1 rounded-full">
                  💡 ARK recommande : {res.recommandation_ark}
                </span>
              )}
            </div>
            <div className="grid grid-cols-1 gap-4">
              {res?.offres?.map((o, i) => (
                <div key={i} className={`rounded-xl border p-5 ${o.score_adequation >= 80 ? 'border-cyan-500/50 bg-cyan-900/10' : 'border-gray-700/50 bg-gray-800/40'}`}>
                  <div className="flex justify-between items-start mb-3">
                    <div>
                      <p className="font-medium text-white">{o.nom_produit}</p>
                      <p className="text-xs text-gray-400">{o.partenaire}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-xl font-bold text-white">{o.prime_mensuelle} €<span className="text-xs text-gray-400">/mois</span></p>
                      <p className="text-xs text-amber-400">Commission : {o.commission_eur} €</p>
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-1 mb-3">
                    {o.garanties_incluses?.slice(0,4).map((g, j) => (
                      <span key={j} className="text-xs bg-green-900/40 text-green-300 px-2 py-0.5 rounded-full">{g}</span>
                    ))}
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <div className="w-20 bg-gray-700 rounded-full h-1.5">
                        <div className="bg-cyan-400 h-1.5 rounded-full" style={{ width: `${o.score_adequation}%` }} />
                      </div>
                      <span className="text-xs text-gray-400">{o.score_adequation}/100</span>
                    </div>
                    <button onClick={() => selectOffre(resultats.id, i)}
                      className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-1.5 rounded-lg text-sm transition">
                      Sélectionner
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })()}

      {/* Historique devis */}
      <div className="space-y-2">
        {dashboard?.recents?.map(d => (
          <div key={d.id} className="bg-gray-800/40 rounded-lg p-3 flex justify-between items-center border border-gray-700/50">
            <div>
              <p className="text-sm font-medium text-white">{d.client_nom} — {d.type_produit}</p>
              <p className="text-xs text-gray-400">{new Date(d.created_at).toLocaleDateString('fr-FR')}</p>
            </div>
            <div className="flex items-center gap-2">
              {d.commission_eur && <span className="text-xs text-amber-400 font-medium">{parseFloat(d.commission_eur).toFixed(0)} €</span>}
              <span className={`text-xs px-2 py-0.5 rounded-full ${d.statut === 'signe' ? 'bg-green-900/50 text-green-400' : d.statut === 'selectionne' ? 'bg-amber-900/50 text-amber-400' : 'bg-gray-700 text-gray-400'}`}>
                {d.statut}
              </span>
            </div>
          </div>
        ))}
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-2xl p-6 w-full max-w-md border border-gray-700 space-y-4">
            <h3 className="text-lg font-semibold text-white">Nouveau devis comparatif</h3>
            <select value={form.typeProduit} onChange={e => setForm(f => ({...f, typeProduit: e.target.value}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white">
              {PRODUITS.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
            <textarea placeholder="Besoins spécifiques du client (ex: villa 200m², garage, piscine)" rows={4}
              onChange={e => setForm(f => ({...f, besoins: { description: e.target.value }}))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white resize-none" />
            <div className="flex gap-3">
              <button onClick={() => setShowForm(false)} className="flex-1 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">Annuler</button>
              <button onClick={comparer} disabled={loading} className="flex-1 py-2 rounded-lg bg-cyan-500 text-black font-medium text-sm disabled:opacity-50">
                {loading ? "⚡ ARK compare..." : "Comparer les offres"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";

export default function RentabiliteDashboard() {
  const [data, setData] = useState(null);
  const [periode, setPeriode] = useState("mois");
  const [loading, setLoading] = useState(false);
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}` };

  const load = async (p) => {
    setLoading(true);
    const res = await fetch(`${API}/api/rentabilite?periode=${p}`, { headers });
    const d = await res.json();
    setData(d);
    setLoading(false);
  };

  useEffect(() => { load(periode); }, []);

  const changePeriode = (p) => { setPeriode(p); load(p); };

  if (!data && loading) return <div className="p-6 text-gray-400">Calcul en cours...</div>;
  if (!data) return null;

  const details = typeof data.details === 'string' ? JSON.parse(data.details) : data.details;
  const byProduit = details?.by_produit || [];
  const byCompagnie = details?.by_compagnie || [];
  const arkAnalyse = details?.ark_analyse;
  const margePct = data.ca_total > 0 ? Math.round((data.marge_brute / data.ca_total) * 100) : 0;

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">💰 Rentabilité Cabinet</h2>
          <p className="text-sm text-gray-400 mt-1">Analyse IA de ton portefeuille</p>
        </div>
        <div className="flex gap-1 bg-gray-800 rounded-lg p-1">
          {["mois","trimestre","annee"].map(p => (
            <button key={p} onClick={() => changePeriode(p)}
              className={`px-3 py-1.5 rounded-md text-xs font-medium transition ${periode === p ? 'bg-cyan-500 text-black' : 'text-gray-400 hover:text-white'}`}>
              {p === "mois" ? "Mois" : p === "trimestre" ? "Trimestre" : "Année"}
            </button>
          ))}
        </div>
      </div>

      {/* KPIs principaux */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: "CA Portefeuille", val: `${parseFloat(data.ca_total||0).toFixed(0)} €`, color: "text-white" },
          { label: "Marge brute est.", val: `${parseFloat(data.marge_brute||0).toFixed(0)} €`, color: "text-green-400" },
          { label: "Taux de marge", val: `${margePct}%`, color: margePct >= 50 ? "text-green-400" : "text-amber-400" },
          { label: "Meilleur produit", val: data.meilleur_produit || "N/A", color: "text-cyan-400" },
        ].map(s => (
          <div key={s.label} className="bg-gray-800/60 rounded-xl p-4 border border-gray-700">
            <p className="text-xs text-gray-400 mb-1">{s.label}</p>
            <p className={`text-xl font-bold ${s.color}`}>{s.val}</p>
          </div>
        ))}
      </div>

      {/* Recommandations ARK */}
      {arkAnalyse?.recommandations && (
        <div className="bg-gradient-to-r from-purple-900/30 to-cyan-900/20 rounded-xl p-4 border border-purple-700/40">
          <p className="text-xs text-purple-300 uppercase tracking-wide mb-3">💡 Recommandations ARK</p>
          <div className="space-y-2">
            {arkAnalyse.recommandations.map((r, i) => (
              <div key={i} className="flex gap-2 text-sm text-gray-200">
                <span className="text-purple-400 shrink-0">{i+1}.</span>{r}
              </div>
            ))}
          </div>
          {arkAnalyse.opportunite_principale && (
            <div className="mt-3 p-2 bg-green-900/20 border border-green-700/30 rounded-lg">
              <p className="text-xs text-green-400">🎯 Opportunité principale</p>
              <p className="text-xs text-gray-200 mt-0.5">{arkAnalyse.opportunite_principale}</p>
            </div>
          )}
        </div>
      )}

      {/* Répartition par produit */}
      {byProduit.length > 0 && (
        <div>
          <p className="text-xs text-gray-400 uppercase tracking-wide mb-3">Répartition par produit</p>
          <div className="space-y-2">
            {byProduit.map((p, i) => {
              const pct = data.ca_total > 0 ? Math.round((p.ca / data.ca_total) * 100) : 0;
              return (
                <div key={i} className="flex items-center gap-3">
                  <span className="text-xs text-gray-300 w-24 truncate">{p.type}</span>
                  <div className="flex-1 bg-gray-700 rounded-full h-2">
                    <div className="bg-cyan-400 h-2 rounded-full transition-all" style={{ width: `${pct}%` }} />
                  </div>
                  <span className="text-xs text-gray-400 w-16 text-right">{parseFloat(p.ca||0).toFixed(0)} €</span>
                  <span className="text-xs text-gray-500 w-8 text-right">{pct}%</span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Top compagnies */}
      {byCompagnie.length > 0 && (
        <div>
          <p className="text-xs text-gray-400 uppercase tracking-wide mb-3">Top compagnies</p>
          <div className="grid grid-cols-2 gap-2">
            {byCompagnie.slice(0,6).map((c, i) => (
              <div key={i} className="bg-gray-800/40 rounded-lg p-3 border border-gray-700/50">
                <p className="text-sm font-medium text-white truncate">{c.compagnie}</p>
                <p className="text-xs text-gray-400">{c.nb_contrats} contrats</p>
                <p className="text-xs text-cyan-400 font-medium">{parseFloat(c.ca||0).toFixed(0)} € CA</p>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

