// /root/courtia/frontend/src/components/leads/LeadInstantInbox.jsx
import { useState, useEffect } from 'react';
import { Zap, PhoneCall, MessageSquare, UserPlus, Loader2, ExternalLink } from 'lucide-react';

const STATUS_LABELS = {
  new: { label: 'Nouveau', color: 'cyan' },
  voice_calling: { label: 'Voice en cours', color: 'purple' },
  sms_drafted: { label: 'SMS prêt', color: 'amber' },
  qualified: { label: 'Qualifié', color: 'emerald' },
  converted: { label: 'Converti client', color: 'emerald' }
};

export default function LeadInstantInbox({ apiBase = '/api', authToken }) {
  const [leads, setLeads] = useState([]);
  const [widgets, setWidgets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [showWidgets, setShowWidgets] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const [l, w] = await Promise.all([
        fetch(`${apiBase}/leads${filter !== 'all' ? `?status=${filter}` : ''}`, { headers: { 'Authorization': `Bearer ${authToken}` } }).then(r => r.json()),
        fetch(`${apiBase}/leads/widgets`, { headers: { 'Authorization': `Bearer ${authToken}` } }).then(r => r.json())
      ]);
      if (l.success) setLeads(l.leads);
      if (w.success) setWidgets(w.widgets);
    } finally { setLoading(false); }
  };

  useEffect(() => { load(); }, [filter]);

  const convert = async (id) => {
    const r = await fetch(`${apiBase}/leads/${id}/convert`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } });
    const d = await r.json();
    if (d.success) {
      alert(d.already_converted ? `Déjà converti — client ${d.client_id}` : `Converti en client ${d.client_id}`);
      load();
    }
  };

  return (
    <div className="space-y-5">
      <div className="rounded-3xl bg-gradient-to-br from-slate-900/80 to-slate-950/90 border border-cyan-500/20 backdrop-blur-xl p-6">
        <div className="flex items-center justify-between gap-4 flex-wrap mb-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-cyan-400 to-purple-500 flex items-center justify-center">
              <Zap className="w-6 h-6 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-semibold text-white">Lead Instant</h2>
              <p className="text-xs text-slate-400">Qualification IA en 60 secondes — Voice ou SMS automatique</p>
            </div>
          </div>
          <button onClick={() => setShowWidgets(!showWidgets)} className="px-3 py-2 rounded-xl bg-slate-800/60 hover:bg-slate-700/60 text-slate-200 text-sm border border-slate-700/50">
            {showWidgets ? 'Voir leads' : `Widgets (${widgets.length})`}
          </button>
        </div>

        <div className="flex gap-2 overflow-x-auto">
          {['all', 'new', 'voice_calling', 'sms_drafted', 'qualified', 'converted'].map(s => (
            <button key={s} onClick={() => setFilter(s)} className={`px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap ${filter === s ? 'bg-cyan-500/20 text-cyan-200 border border-cyan-500/40' : 'bg-slate-800/40 text-slate-400 border border-slate-700/50'}`}>
              {s === 'all' ? 'Tous' : STATUS_LABELS[s]?.label || s}
            </button>
          ))}
        </div>
      </div>

      {loading ? <div className="rounded-2xl bg-slate-900/60 border border-slate-700/50 p-12 flex items-center justify-center"><Loader2 className="w-6 h-6 text-cyan-400 animate-spin" /></div> :
       showWidgets ? <WidgetsList widgets={widgets} apiBase={apiBase} authToken={authToken} onReload={load} /> :
       leads.length === 0 ? <div className="text-slate-400 text-sm text-center py-12 rounded-2xl bg-slate-900/40 border border-slate-700/30">Aucun lead pour le moment. Configure un widget de capture pour commencer.</div> :
       <div className="space-y-2">
         {leads.map(l => {
           const status = STATUS_LABELS[l.status] || { label: l.status, color: 'slate' };
           const scoreColor = l.lead_score >= 70 ? 'emerald' : l.lead_score >= 40 ? 'amber' : 'red';
           const sCol = { emerald: 'text-emerald-300', amber: 'text-amber-300', red: 'text-red-300' };
           return (
             <div key={l.id} className="rounded-xl bg-slate-800/40 border border-slate-700/50 p-4">
               <div className="flex items-start justify-between gap-3 flex-wrap">
                 <div className="flex-1 min-w-0">
                   <div className="flex items-center gap-2 flex-wrap mb-1">
                     <div className="text-white font-medium">{l.nom} {l.prenom || ''}</div>
                     <span className={`text-[10px] uppercase font-semibold px-2 py-0.5 rounded-full bg-${status.color}-500/15 text-${status.color}-300 border border-${status.color}-500/30`}>{status.label}</span>
                     {l.contact_method_used && <span className="text-[10px] text-slate-400">via {l.contact_method_used}</span>}
                   </div>
                   <div className="text-xs text-slate-400">{l.email} · {l.telephone || '—'}</div>
                   <div className="text-xs text-slate-300 mt-1">{l.type_demande || 'Pas de précision'}</div>
                   {l.raison_sociale && <div className="text-xs text-cyan-300 mt-1">🏢 {l.raison_sociale} · {l.secteur_activite}</div>}
                 </div>
                 <div className="text-right">
                   <div className={`text-2xl font-bold ${sCol[scoreColor]}`}>{l.lead_score}<span className="text-xs text-slate-400">/100</span></div>
                   <div className="text-[10px] uppercase text-slate-400">score</div>
                 </div>
               </div>
               {l.status !== 'converted' && (
                 <div className="flex gap-2 mt-3">
                   <button onClick={() => convert(l.id)} className="px-3 py-1.5 rounded-lg bg-cyan-500/20 border border-cyan-500/40 text-cyan-200 text-xs flex items-center gap-1.5">
                     <UserPlus className="w-3.5 h-3.5" /> Convertir en client
                   </button>
                   {l.telephone && <a href={`tel:${l.telephone}`} className="px-3 py-1.5 rounded-lg bg-slate-700 text-white text-xs flex items-center gap-1.5"><PhoneCall className="w-3.5 h-3.5" /> Appeler</a>}
                 </div>
               )}
             </div>
           );
         })}
       </div>
      }
    </div>
  );
}

function WidgetsList({ widgets, apiBase, authToken, onReload }) {
  const [creating, setCreating] = useState(false);
  const create = async () => {
    const name = prompt('Nom du widget :');
    if (!name) return;
    const produit = prompt('Produit cible (ex: auto, sante, rc_pro) :');
    setCreating(true);
    await fetch(`${apiBase}/leads/widgets`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${authToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, produit_cible: produit, fields_config: { nom: true, email: true, telephone: true, type_demande: true } })
    });
    setCreating(false);
    onReload();
  };

  return (
    <div className="space-y-3">
      <button onClick={create} disabled={creating} className="px-4 py-2.5 rounded-xl bg-gradient-to-r from-cyan-500 to-purple-500 text-white text-sm font-medium hover:opacity-90 disabled:opacity-50">
        {creating ? 'Création…' : '+ Nouveau widget'}
      </button>
      {widgets.map(w => (
        <div key={w.id} className="rounded-xl bg-slate-800/40 border border-slate-700/50 p-4">
          <div className="text-white font-medium">{w.name}</div>
          <div className="text-xs text-slate-400">Produit : {w.produit_cible} · {w.total_captured} captures · {w.total_converted} convertis</div>
          <div className="mt-2 rounded-lg bg-slate-900 border border-slate-700 p-2.5">
            <div className="text-[10px] uppercase text-slate-400 mb-1">URL de soumission</div>
            <code className="text-xs text-cyan-200 break-all">POST /api/leads/widget/{w.widget_token}</code>
          </div>
        </div>
      ))}
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";

export default function ArkNegociateur() {
  const [negociations, setNegociations] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    compagnieNom: "", typeNegociation: "revalorisation_commission",
    volumePorrefeuille: "", sinistraliteRate: "",
    ancienneteMois: "", commissionActuelle: "", commissionCible: ""
  });
  const token = localStorage.getItem("token");
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };

  useEffect(() => {
    fetch(`${API}/api/negociation/list`, { headers }).then(r => r.json()).then(setNegociations);
  }, []);

  async function buildDossier() {
    setLoading(true);
    const res = await fetch(`${API}/api/negociation/build`, { method: "POST", headers, body: JSON.stringify(form) });
    const data = await res.json();
    setLoading(false);
    setNegociations(prev => [data, ...prev]);
    setShowForm(false);
  }

  async function downloadPDF(id) {
    const res = await fetch(`${API}/api/negociation/${id}/rapport-pdf`, { method: "POST", headers });
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    window.open(url);
  }

  const typeLabels = {
    revalorisation_commission: "Revalorisation commission",
    extension_gamme: "Extension de gamme",
    exclusivite: "Accord d'exclusivité",
    conditions_speciales: "Conditions spéciales"
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-semibold text-white">🤝 ARK Négociateur Compagnie</h2>
          <p className="text-sm text-gray-400 mt-1">Dossier argumenté IA · Stratégie + PDF téléchargeable</p>
        </div>
        <button onClick={() => setShowForm(true)} className="bg-cyan-500 hover:bg-cyan-400 text-black font-medium px-4 py-2 rounded-lg text-sm transition">
          + Préparer une négociation
        </button>
      </div>

      <div className="space-y-3">
        {negociations.length === 0 && (
          <div className="text-center py-12 text-gray-500">
            <p className="text-4xl mb-3">🏢</p>
            <p className="text-sm">Aucune négociation préparée.</p>
            <p className="text-xs mt-1">ARK construit ton dossier en 30 secondes.</p>
          </div>
        )}
        {negociations.map(n => {
          const dossier = typeof n.dossier_arguments === 'string' ? JSON.parse(n.dossier_arguments) : n.dossier_arguments;
          return (
            <div key={n.id} className="bg-gray-800/40 rounded-xl border border-gray-700/50 p-5">
              <div className="flex justify-between items-start">
                <div>
                  <p className="font-medium text-white">{n.compagnie_nom}</p>
                  <p className="text-xs text-gray-400 mt-1">{typeLabels[n.type_negociation]} · {n.commission_actuelle}% → {n.commission_cible}%</p>
                  <p className="text-xs text-gray-500">{n.volume_portefeuille} contrats · Sinistralité {n.sinistralite_rate}%</p>
                </div>
                <button onClick={() => downloadPDF(n.id)} className="text-sm bg-gray-700 hover:bg-gray-600 text-white px-3 py-1.5 rounded-lg transition">
                  📄 Télécharger
                </button>
              </div>

              {dossier?.synthese_executive && (
                <div className="mt-4 p-3 bg-gray-900/50 rounded-lg border border-gray-700/30">
                  <p className="text-xs text-cyan-400 mb-1">Synthèse ARK</p>
                  <p className="text-xs text-gray-300">{dossier.synthese_executive}</p>
                </div>
              )}

              {dossier?.arguments_principaux?.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-1">
                  {dossier.arguments_principaux.slice(0, 3).map((a, i) => (
                    <span key={i} className="text-xs bg-gray-700 text-gray-300 px-2 py-0.5 rounded-full">{a.titre}</span>
                  ))}
                </div>
              )}

              {dossier?.phrase_ouverture && (
                <div className="mt-3 p-2 border border-purple-700/40 rounded-lg">
                  <p className="text-xs text-purple-400">Phrase d'ouverture recommandée</p>
                  <p className="text-xs text-gray-200 mt-1 italic">"{dossier.phrase_ouverture}"</p>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-2xl p-6 w-full max-w-md border border-gray-700 space-y-4">
            <h3 className="text-lg font-semibold text-white">Nouvelle négociation</h3>
            <input placeholder="Nom de la compagnie (ex: AXA, MMA...)" value={form.compagnieNom}
              onChange={e => setForm(f => ({ ...f, compagnieNom: e.target.value }))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            <select value={form.typeNegociation} onChange={e => setForm(f => ({ ...f, typeNegociation: e.target.value }))}
              className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white">
              {Object.entries(typeLabels).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </select>
            <div className="grid grid-cols-2 gap-3">
              <input type="number" placeholder="Nb contrats" value={form.volumePorrefeuille}
                onChange={e => setForm(f => ({ ...f, volumePorrefeuille: e.target.value }))}
                className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
              <input type="number" placeholder="Sinistralité %" value={form.sinistraliteRate}
                onChange={e => setForm(f => ({ ...f, sinistraliteRate: e.target.value }))}
                className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
              <input type="number" placeholder="Ancienneté (mois)" value={form.ancienneteMois}
                onChange={e => setForm(f => ({ ...f, ancienneteMois: e.target.value }))}
                className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
              <input type="number" placeholder="Commission actuelle %" value={form.commissionActuelle}
                onChange={e => setForm(f => ({ ...f, commissionActuelle: e.target.value }))}
                className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
              <input type="number" placeholder="Commission cible %" value={form.commissionCible}
                onChange={e => setForm(f => ({ ...f, commissionCible: e.target.value }))}
                className="col-span-2 bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white" />
            </div>
            <div className="flex gap-3">
              <button onClick={() => setShowForm(false)} className="flex-1 py-2 rounded-lg border border-gray-600 text-gray-300 text-sm">Annuler</button>
              <button onClick={buildDossier} disabled={loading}
                className="flex-1 py-2 rounded-lg bg-cyan-500 text-black font-medium text-sm disabled:opacity-50">
                {loading ? "ARK analyse..." : "Construire le dossier"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

const API = import.meta.env.VITE_API_URL || "https://api.courtiark.fr";

export default function ParrainageTracker() {
  const [data, setData] = useState(null);
  const [copied, setCopied] = useState(false);
  const token = localStorage.getItem("token");

  useEffect(() => {
    fetch(`${API}/api/parrainage/dashboard`, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json()).then(setData);
  }, []);

  function copyLink() {
    navigator.clipboard.writeText(data.lien_parrainage);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  if (!data) return <div className="p-6 text-gray-400">Chargement...</div>;

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-xl font-semibold text-white">🎁 Programme Parrainage</h2>
        <p className="text-sm text-gray-400 mt-1">
          Tu gagnes <span className="text-green-400 font-medium">{data.reward_referrer} €</span> par filleul converti ·
          Ton filleul gagne <span className="text-cyan-400 font-medium">{data.reward_referee} €</span> sur son premier mois
        </p>
      </div>

      {/* Code + lien */}
      <div className="bg-gradient-to-r from-cyan-900/30 to-purple-900/30 rounded-xl p-5 border border-cyan-700/40">
        <p className="text-xs text-gray-400 uppercase tracking-wide mb-2">Ton code de parrainage</p>
        <div className="flex items-center gap-3">
          <span className="text-2xl font-bold text-cyan-400 tracking-widest">{data.code}</span>
        </div>
        <div className="mt-3 flex items-center gap-2">
          <input value={data.lien_parrainage} readOnly
            className="flex-1 bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-xs text-gray-300" />
          <button onClick={copyLink}
            className="bg-cyan-500 hover:bg-cyan-400 text-black px-4 py-2 rounded-lg text-sm font-medium transition">
            {copied ? "✓ Copié" : "Copier"}
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4">
        {[
          { label: "Invitations envoyées", val: data.total_referrals, color: "text-white" },
          { label: "Conversions", val: data.total_conversions, color: "text-green-400" },
          { label: "Gains cumulés", val: `${data.total_reward_eur} €`, color: "text-amber-400" },
        ].map(s => (
          <div key={s.label} className="bg-gray-800/60 rounded-xl p-4 border border-gray-700 text-center">
            <p className={`text-xl font-bold ${s.color}`}>{s.val}</p>
            <p className="text-xs text-gray-400 mt-1">{s.label}</p>
          </div>
        ))}
      </div>

      {/* Liste filleuls */}
      {data.referrals?.length > 0 && (
        <div className="space-y-2">
          <p className="text-xs text-gray-400 uppercase tracking-wide">Filleuls</p>
          {data.referrals.map(r => (
            <div key={r.id} className="bg-gray-800/40 rounded-lg p-3 flex justify-between items-center border border-gray-700/50">
              <div>
                <p className="text-sm text-white">{r.referee_email}</p>
                <p className="text-xs text-gray-400">{r.filleul_cabinet || "En attente d'inscription"}</p>
              </div>
              <div className="flex items-center gap-2">
                <span className={`text-xs px-2 py-1 rounded-full ${
                  r.statut === "converted" ? "bg-green-900/50 text-green-400" : "bg-gray-700 text-gray-400"
                }`}>{r.statut === "converted" ? `+${r.reward_eur} €` : "En attente"}</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* CTA partage */}
      <div className="grid grid-cols-2 gap-3">
        <button onClick={() => window.open(`mailto:?subject=Découvre COURTIA&body=Utilise mon lien : ${data.lien_parrainage}`)}
          className="py-3 rounded-xl border border-gray-600 text-gray-300 text-sm hover:bg-gray-800 transition">
          📧 Inviter par email
        </button>
        <button onClick={() => window.open(`https://wa.me/?text=Utilise mon code COURTIA ${data.code} : ${data.lien_parrainage}`)}
          className="py-3 rounded-xl bg-green-700 hover:bg-green-600 text-white text-sm transition">
          💬 Inviter sur WhatsApp
        </button>
      </div>
    </div>
  );
}

