          </div>
          <h2 style="font-size:18px;font-weight:700;margin:0;">${course.title}</h2>
        </div>
        <button onclick="this.closest('[style*=\\'position:fixed\\']').remove()" style="background:none;border:none;color:rgba(255,255,255,0.4);font-size:20px;cursor:pointer;">✕</button>
      </div>
      <div style="white-space:pre-wrap;font-size:13px;color:rgba(255,255,255,0.7);line-height:1.7;margin-bottom:1.5rem;">${course.content}</div>
      <div style="border:1px solid rgba(255,255,255,0.06);border-radius:12px;padding:1rem;margin-bottom:1.5rem;background:rgba(255,255,255,0.02);">
        <p style="font-size:12px;font-weight:600;color:rgba(255,255,255,0.5);margin-bottom:0.75rem;">Points clés</p>
        ${(course.key_points || []).map(kp => `<div style="display:flex;align-items:flex-start;gap:0.5rem;margin-bottom:0.5rem;font-size:12px;color:rgba(255,255,255,0.6);"><span style="color:#a78bfa;">→</span>${kp}</div>`).join('')}
      </div>
      <button onclick="completeCourse(this, ${course.id}, '${courseSlug}')"
        style="width:100%;padding:12px;border:none;border-radius:12px;font-size:13px;font-weight:600;background:linear-gradient(135deg,rgba(139,92,246,0.2),rgba(59,130,246,0.15));color:#c4b5fd;border:1px solid rgba(139,92,246,0.25);cursor:pointer;">
        Marquer comme terminé (+${course.xp_reward} XP)
      </button>
      <p id="course-feedback" style="text-align:center;font-size:12px;margin-top:0.75rem;color:rgba(255,255,255,0.3);display:none;"></p>
    </div>
  `
  document.body.appendChild(modal)
}

window.completeCourse = async (btn, courseId, _slug) => {
  const token = localStorage.getItem('courtia_token') || localStorage.getItem('token')
  const API_URL = import.meta.env.VITE_API_URL || '/api'
  try {
    const res = await fetch(`${API_URL}/api/academy/courses/${courseId}/complete`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ answers: [] })
    })
    const data = await res.json()
    if (data.success) {
      btn.textContent = '✅ Terminé !'
      btn.style.background = 'rgba(16,185,129,0.15)'
      btn.style.color = '#6ee7b7'
      btn.style.border = '1px solid rgba(16,185,129,0.25)'
      btn.disabled = true
      document.getElementById('course-feedback').style.display = 'block'
      document.getElementById('course-feedback').textContent = `+${data.data?.xpGained || 0} XP gagnés !`
      // Reload page component in background
      setTimeout(() => {
        document.querySelector('[style*="position:fixed"]')?.remove()
        window.location.reload()
      }, 1500)
    }
  } catch (_err) {
    document.getElementById('course-feedback').style.display = 'block'
    document.getElementById('course-feedback').textContent = 'Erreur lors de la validation.'
  }
}

import { useEffect, useState } from 'react'
import { MessageCircle, RefreshCw } from 'lucide-react'
import AuroraEmptyState from '../components/brand/AuroraEmptyState'
import { publicApiFetch } from '../lib/adminApi'

const statusLabels = {
  new: 'Nouveau',
  seen: 'Vu',
  resolved: 'Traité',
}

export default function AdminFeedback() {
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  async function loadFeedback() {
    setLoading(true)
    setError('')
    try {
      const res = await publicApiFetch('/admin/feedback')
      if (!res.ok) throw new Error('feedback_unavailable')
      const data = await res.json()
      setRows(Array.isArray(data.rows) ? data.rows : [])
    } catch {
      setError('Feedback indisponible.')
    } finally {
      setLoading(false)
    }
  }

  async function updateStatus(id, status) {
    await publicApiFetch(`/admin/feedback/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status }),
    }).catch(() => {})
    await loadFeedback()
  }

  useEffect(() => { loadFeedback() }, [])

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 24, color: '#fff' }}>Feedback utilisateurs</h1>
          <p style={{ margin: '6px 0 0', fontSize: 13, color: 'rgba(255,255,255,0.46)' }}>
            Bugs, idées, frictions et signaux des premiers cabinets.
          </p>
        </div>
        <button
          type="button"
          onClick={loadFeedback}
          style={{ border: '1px solid rgba(255,255,255,0.16)', background: 'rgba(255,255,255,0.05)', color: '#fff', borderRadius: 10, padding: '9px 12px', display: 'inline-flex', alignItems: 'center', gap: 7, cursor: 'pointer' }}
        >
          <RefreshCw size={14} /> Actualiser
        </button>
      </div>

      {loading ? (
        <p style={{ color: 'rgba(255,255,255,0.55)' }}>Chargement...</p>
      ) : error ? (
        <AuroraEmptyState icon={MessageCircle} title="Feedback indisponible" subtitle={error} />
      ) : rows.length === 0 ? (
        <AuroraEmptyState icon={MessageCircle} title="Aucun feedback pour le moment" subtitle="Les retours envoyés depuis l’app apparaîtront ici." />
      ) : (
        <div style={{ display: 'grid', gap: 12 }}>
          {rows.map((item) => (
            <article key={item.id} className="courtia-depth-card" style={{ border: '1px solid rgba(255,255,255,0.08)', background: 'rgba(255,255,255,0.03)', borderRadius: 12, padding: 16 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'flex-start' }}>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                    <span style={{ borderRadius: 999, background: 'rgba(34,211,238,0.12)', color: '#8eeaff', padding: '4px 8px', fontSize: 11, fontWeight: 800, textTransform: 'uppercase' }}>{item.type}</span>
                    <span style={{ color: 'rgba(255,255,255,0.42)', fontSize: 12 }}>{item.page || 'Page inconnue'}</span>
                  </div>
                  <p style={{ margin: 0, color: '#fff', fontSize: 14, lineHeight: 1.55 }}>{item.message}</p>
                  <p style={{ margin: '10px 0 0', color: 'rgba(255,255,255,0.42)', fontSize: 12 }}>
                    {item.email || `Utilisateur #${item.user_id}`} · {new Date(item.created_at).toLocaleString('fr-FR')}
                  </p>
                </div>
                <select
                  value={item.status}
                  onChange={(e) => updateStatus(item.id, e.target.value)}
                  style={{ border: '1px solid rgba(255,255,255,0.14)', borderRadius: 9, background: 'rgba(0,0,0,0.24)', color: '#fff', padding: '7px 9px', fontSize: 12 }}
                >
                  {Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}
                </select>
              </div>
            </article>
          ))}
        </div>
      )}
    </div>
  )
}

