                transition: 'border-color 0.15s, box-shadow 0.15s'
              }}
            />
            {orias.length > 0 && !oriasValid && (
              <p style={{ fontSize: 11, color: '#ef4444', margin: '4px 0 0' }}>8 chiffres requis</p>
