        {/* TAB CONTENT */}
        <AnimatePresence mode="wait">
          {tab === 'vue360' && (
            <Vue360Tab key="vue360" client={client}
              contracts={DEMO_CONTRACTS} devis={DEMO_DEVIS}
              docs={DEMO_DOCS} tasks={DEMO_TASKS} history={DEMO_HISTORY}
