// ─── Aurora Card (glassmorphism) ─────────────────────────────────
function AuroraCard({ children, padding = 20, hover = true, accent, onClick, style }) {
  return (
    <div
      onClick={onClick}
      style={{
        background: T.cardBg,
        border: `1px solid ${T.cardBorder}`,
