    try {
      setLoading(true)
      setError(false)
      const [userRes] = await Promise.all([
        getSessionUser().then(u => ({ data: u || {} })).catch(() => ({ data: {} })),
      ])
      setUser(userRes.data || {})

      try {
        const [clientsRes, tasksRes] = await Promise.all([
          api.get('/clients?limit=300').catch(() => ({ data: [] })),
          api.get('/taches').catch(() => ({ data: [] })),
