        const realPriorities = computeDailyPriorities(clientsRes.data, tasksRes.data)
        if (realPriorities && realPriorities.totalActions > 0) {
          setPriorities(realPriorities)
          setHasRealData(true)
        } else {
          setHasRealData(false)
        }
      } catch {
        setHasRealData(false)
      }
    } catch {
      setError(true)
      setHasRealData(false)
    }
    finally { setLoading(false) }
  }, [])

