                c.status === 'paused' ? 'bg-amber-50 text-amber-700' : 'bg-gray-50 text-gray-500'
              }`}>
                {c.status === 'running' || c.status === 'active' ? 'Actif' : c.status === 'paused' ? 'Pause' : 'Brouillon'}
