                        <span style={{ fontSize: 11, color: variance > 0 ? '#10B981' : '#EF4444', marginLeft: 6 }}>
                          ({variance > 0 ? '+' : ''}{variance.toLocaleString('fr-FR')})
                        </span>
                      )}
                    </td>
                    <td style={{ padding: 16, textAlign: 'center' }}>
                      <span style={{ padding: '4px 12px', borderRadius: 20, background: statusStyle.bg, color: statusStyle.text, fontSize: 12, fontWeight: 500 }}>
                        {statusStyle.label}
                      </span>
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* Par compagnie */}
      {stats?.by_insurer?.length > 0 && (
        <div style={{ marginTop: 32 }}>
          <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 16, color: '#0F172A' }}>Par compagnie</h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
            {stats.by_insurer.map((ins, i) => (
              <motion.div
                key={ins.insurer}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                style={{ background: 'white', borderRadius: 12, padding: 20, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
                  <Building2 size={20} color="#8B5CF6" />
                  <span style={{ fontWeight: 600, color: '#0F172A' }}>{ins.insurer}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <div>
                    <div style={{ fontSize: 12, color: '#64748B' }}>Reçu</div>
                    <div style={{ fontSize: 18, fontWeight: 600, color: '#10B981' }}>{ins.received_amount_eur?.toLocaleString('fr-FR')} €</div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div style={{ fontSize: 12, color: '#64748B' }}>Commissions</div>
                    <div style={{ fontSize: 18, fontWeight: 600, color: '#0F172A' }}>{ins.count}</div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      )}

      {/* Modal Règles */}
      <AnimatePresence>
        {showRulesModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}
            onClick={() => setShowRulesModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={e => e.stopPropagation()}
              style={{ background: 'white', borderRadius: 20, padding: 32, width: 600, maxHeight: '80vh', overflow: 'auto' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <h2 style={{ fontSize: 20, fontWeight: 700, margin: 0 }}>Règles de commission</h2>
                <button onClick={() => setShowRulesModal(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
                  <X size={20} color="#64748B" />
                </button>
              </div>

              {rules.length === 0 ? (
                <p style={{ color: '#64748B', textAlign: 'center', padding: 40 }}>Aucune règle configurée</p>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  {rules.map(rule => (
                    <div key={rule.id} style={{ padding: 16, background: '#F8FAFC', borderRadius: 12, border: '1px solid #E2E8F0' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <div style={{ fontWeight: 600 }}>{rule.product_type || 'Tous produits'}</div>
                          <div style={{ fontSize: 13, color: '#64748B' }}>{rule.company || 'Toutes compagnies'}</div>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                          <div style={{ fontWeight: 600, color: '#8B5CF6' }}>{rule.rate_percent}%</div>
                          {rule.flat_fee_eur > 0 && <div style={{ fontSize: 12, color: '#64748B' }}>+ {rule.flat_fee_eur}€</div>}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { FileText, FileCheck, Shield, Sparkles, Download, Eye, Clock, User } from 'lucide-react';
import { AuroraPageHeader, AuroraCard, AuroraButton, AuroraSelect, AuroraBadge, AuroraSkeleton, AuroraEmptyState, AuroraDialog, useToast } from '../../components/aurora';

const API_BASE = '/api';
const getToken = () => localStorage.getItem('token');

const docTypes = [
  { id: 'ipid', label: 'IPID', description: "Document d'information produit", icon: FileText, color: '#3b82f6' },
  { id: 'dda', label: 'DDA', description: 'Devoir de conseil', icon: FileCheck, color: '#22c55e' },
  { id: 'dc', label: 'Document Contractuel', description: 'Conditions particulières', icon: Shield, color: '#a855f7' },
];

export function ComposeV2() {
  const toast = useToast();
  const [clients, setClients] = useState([]);
  const [selectedClient, setSelectedClient] = useState('');
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(null);
  const [previewDoc, setPreviewDoc] = useState(null);

  useEffect(() => {
    const load = async () => {
      try {
        const [cRes, dRes] = await Promise.all([
          fetch(`${API_BASE}/clients?limit=100`, { headers: { Authorization: `Bearer ${getToken()}` } }).then(r => r.json()),
          fetch(`${API_BASE}/compose/documents`, { headers: { Authorization: `Bearer ${getToken()}` } }).then(r => r.json()),
        ]);
        setClients(cRes.clients || cRes || []);
        setDocuments(dRes.documents || dRes || []);
      } catch (e) { toast.error('Erreur chargement'); }
      setLoading(false);
    };
    load();
  }, []);

  const generate = async (type) => {
    if (!selectedClient) { toast.warning('Sélectionnez un client'); return; }
    setGenerating(type);
    try {
      const res = await fetch(`${API_BASE}/compose/generate`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${getToken()}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, clientId: selectedClient }),
      });
      const doc = await res.json();
      setDocuments(prev => [doc, ...prev]);
      toast.success(`${type.toUpperCase()} généré`);
    } catch (e) { toast.error('Erreur génération'); }
    setGenerating(null);
  };

  return (
    <div style={{ padding: 'var(--aurora-space-6)', maxWidth: 1400, margin: '0 auto' }}>
      <AuroraPageHeader title="ARK Compose" subtitle="Génération automatique de documents réglementaires" />
      <div style={{ maxWidth: 400, marginBottom: 'var(--aurora-space-4)' }}>
        <AuroraSelect label="Client" placeholder="Sélectionner..." options={clients.map(c => ({ value: c.id, label: `${c.prenom || ''} ${c.nom || ''}` }))} value={selectedClient} onChange={setSelectedClient} />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 'var(--aurora-space-4)', marginBottom: 'var(--aurora-space-6)' }}>
        {docTypes.map(doc => (
          <motion.div key={doc.id} whileHover={{ y: -4 }}>
            <AuroraCard style={{ borderTop: `3px solid ${doc.color}` }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--aurora-space-3)', marginBottom: 'var(--aurora-space-3)' }}>
                <div style={{ width: 44, height: 44, borderRadius: 'var(--aurora-radius-md)', background: `${doc.color}20`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <doc.icon size={22} style={{ color: doc.color }} />
                </div>
                <div><h3 style={{ margin: 0, fontSize: 'var(--aurora-font-lg)', fontWeight: 600 }}>{doc.label}</h3><p style={{ margin: 0, fontSize: 'var(--aurora-font-sm)', color: 'var(--aurora-text-secondary)' }}>{doc.description}</p></div>
              </div>
              <AuroraButton variant="secondary" style={{ width: '100%' }} onClick={() => generate(doc.id)} disabled={generating === doc.id}>
                <Sparkles size={16} style={{ marginRight: 8 }} />{generating === doc.id ? 'Génération...' : 'Générer'}
              </AuroraButton>
            </AuroraCard>
          </motion.div>
        ))}
      </div>
      <h3 style={{ fontSize: 'var(--aurora-font-lg)', fontWeight: 600, marginBottom: 'var(--aurora-space-3)' }}>Documents générés</h3>
      {loading ? <AuroraSkeleton lines={4} /> : documents.length === 0 ? <AuroraEmptyState icon={FileText} title="Aucun document" description="Générez votre premier document" /> : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--aurora-space-2)' }}>
          {documents.map((doc, i) => (
            <motion.div key={doc.id || i} initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ display: 'flex', alignItems: 'center', gap: 'var(--aurora-space-3)', padding: 'var(--aurora-space-3)', background: 'var(--aurora-bg-card)', border: '1px solid var(--aurora-border-subtle)', borderRadius: 'var(--aurora-radius-md)' }} whileHover={{ background: 'var(--aurora-bg-hover)' }}>
              <FileText size={20} style={{ color: 'var(--aurora-accent)' }} />
              <div style={{ flex: 1 }}><div style={{ fontWeight: 500 }}>{doc.type?.toUpperCase()} - {doc.clientName || 'Client'}</div><div style={{ fontSize: 'var(--aurora-font-xs)', color: 'var(--aurora-text-muted)' }}><Clock size={12} style={{ marginRight: 4, verticalAlign: 'middle' }} />{new Date(doc.createdAt).toLocaleDateString('fr-FR')}</div></div>
              <AuroraButton variant="ghost" size="sm" onClick={() => setPreviewDoc(doc)}><Eye size={16} /></AuroraButton>
              <AuroraButton variant="ghost" size="sm"><Download size={16} /></AuroraButton>
            </motion.div>
          ))}
        </div>
      )}
      <AuroraDialog open={!!previewDoc} onClose={() => setPreviewDoc(null)} title={previewDoc?.type?.toUpperCase()} size="lg">
        <div style={{ whiteSpace: 'pre-wrap', fontSize: 'var(--aurora-font-sm)', lineHeight: 1.6 }}>{previewDoc?.content || 'Aperçu non disponible'}</div>
      </AuroraDialog>
    </div>
  );
}

export default ComposeV2;

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { 
  FileSpreadsheet, Download, TrendingUp, TrendingDown, Calculator,
  Calendar, Building2, PieChart, RefreshCw, FileText, Euro, Receipt
} from 'lucide-react'
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, AreaChart, Area } from 'recharts'
import api from '../../api'

const MONTHS = ['', 'Janv', 'Févr', 'Mars', 'Avr', 'Mai', 'Juin', 'Juil', 'Août', 'Sept', 'Oct', 'Nov', 'Déc']

export default function ComptabiliteV2() {
  const [summary, setSummary] = useState(null)
  const [entries, setEntries] = useState([])
  const [loading, setLoading] = useState(true)
  const [year, setYear] = useState(new Date().getFullYear())
  const [period, setPeriod] = useState('year') // year, quarter, month
  const [generating, setGenerating] = useState(false)

  useEffect(() => {
    loadData()
  }, [year])

  async function loadData() {
    setLoading(true)
    try {
      const [summaryRes, entriesRes] = await Promise.all([
        api.get(`/accounting/summary/${year}`),
        api.get('/accounting/entries', { params: { year, limit: 50 } })
      ])
      setSummary(summaryRes.data)
      setEntries(entriesRes.data?.data || [])
    } catch (err) {
      console.error('Failed to load accounting data:', err)
    } finally {
      setLoading(false)
    }
  }

  async function downloadFEC() {
    setGenerating(true)
    try {
      const params = period === 'year' 
        ? { year } 
        : period === 'quarter'
        ? { start: `${year}-${(Math.floor((new Date().getMonth()) / 3) * 3) + 1}-01`, end: `${year}-${(Math.floor((new Date().getMonth()) / 3) * 3) + 3}-30` }
        : { start: `${year}-${new Date().getMonth() + 1}-01`, end: `${year}-${new Date().getMonth() + 1}-31` }

      const res = await api.get('/accounting/fec', { params, responseType: 'blob' })

      const url = window.URL.createObjectURL(new Blob([res.data]))
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', `FEC_${year}.txt`)
      document.body.appendChild(link)
      link.click()
      link.remove()
    } catch (err) {
      alert('Erreur export FEC: ' + (err.response?.data?.error || err.message))
    } finally {
      setGenerating(false)
    }
  }

  async function generateFromCommissions() {
    setGenerating(true)
    try {
      const startDate = `${year}-01-01`
      const endDate = `${year}-12-31`

      const res = await api.post('/accounting/generate-from-commissions', { startDate, endDate })
      alert(`${res.data.generated} écritures générées depuis les commissions`)
      loadData()
    } catch (err) {
      alert('Erreur: ' + (err.response?.data?.error || err.message))
    } finally {
      setGenerating(false)
    }
  }

  const chartData = summary?.by_month?.map(m => ({
    name: MONTHS[m.month],
    Produits: m.produits_eur,
    Charges: m.charges_eur,
    Résultat: m.resultat_eur
  })) || []

  const resultatPositif = (summary?.totals?.resultat_net_eur || 0) >= 0

  return (
    <div style={{ padding: 24, maxWidth: 1400, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 32 }}>
        <div>
          <h1 style={{ fontSize: 28, fontWeight: 700, color: '#0F172A', margin: 0, display: 'flex', alignItems: 'center', gap: 12 }}>
            <FileSpreadsheet size={28} color="#8B5CF6" />
            Comptabilité
          </h1>
          <p style={{ color: '#64748B', marginTop: 4 }}>Export FEC et suivi comptable</p>
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          <select
            value={year}
            onChange={e => setYear(parseInt(e.target.value, 10))}
            style={{ padding: '10px 16px', border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14, background: 'white' }}
          >
            {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
          </select>
          <select
            value={period}
            onChange={e => setPeriod(e.target.value)}
            style={{ padding: '10px 16px', border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14, background: 'white' }}
          >
            <option value="year">Année complète</option>
            <option value="quarter">Trimestre en cours</option>
            <option value="month">Mois en cours</option>
          </select>
          <button
            onClick={generateFromCommissions}
            disabled={generating}
            style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '10px 16px', background: '#F0F9FF', color: '#0369A1', border: 'none', borderRadius: 10, fontSize: 14, fontWeight: 500, cursor: 'pointer' }}
          >
            <Calculator size={16} /> Générer écritures
          </button>
          <button
            onClick={downloadFEC}
            disabled={generating}
            style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '10px 20px', background: 'linear-gradient(135deg, #8B5CF6 0%, #06B6D4 100%)', color: 'white', border: 'none', borderRadius: 10, fontSize: 14, fontWeight: 600, cursor: 'pointer' }}
          >
            <Download size={16} /> {generating ? 'Export...' : 'Télécharger FEC'}
          </button>
        </div>
      </div>

      {loading ? (
        <div style={{ padding: 80, textAlign: 'center', color: '#64748B' }}>Chargement...</div>
      ) : (
        <>
          {/* KPIs */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 20, marginBottom: 32 }}>
            <motion.div 
              initial={{ opacity: 0, y: 20 }} 
              animate={{ opacity: 1, y: 0 }}
              style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                <span style={{ color: '#64748B', fontSize: 14 }}>Chiffre d'affaires</span>
                <TrendingUp size={20} color="#10B981" />
              </div>
              <div style={{ fontSize: 28, fontWeight: 700, color: '#10B981' }}>
                {summary?.totals?.produits_eur?.toLocaleString('fr-FR')} €
              </div>
              <div style={{ fontSize: 12, color: '#64748B', marginTop: 4 }}>
                Commissions encaissées
              </div>
            </motion.div>

            <motion.div 
              initial={{ opacity: 0, y: 20 }} 
              animate={{ opacity: 1, y: 0 }} 
              transition={{ delay: 0.1 }}
              style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                <span style={{ color: '#64748B', fontSize: 14 }}>Charges</span>
                <TrendingDown size={20} color="#EF4444" />
              </div>
              <div style={{ fontSize: 28, fontWeight: 700, color: '#EF4444' }}>
                {summary?.totals?.charges_eur?.toLocaleString('fr-FR')} €
              </div>
              <div style={{ fontSize: 12, color: '#64748B', marginTop: 4 }}>
                Frais déductibles
              </div>
            </motion.div>

            <motion.div 
              initial={{ opacity: 0, y: 20 }} 
              animate={{ opacity: 1, y: 0 }} 
              transition={{ delay: 0.2 }}
              style={{ 
                background: resultatPositif 
                  ? 'linear-gradient(135deg, #10B981 0%, #059669 100%)' 
                  : 'linear-gradient(135deg, #EF4444 0%, #DC2626 100%)', 
                borderRadius: 16, 
                padding: 24, 
                color: 'white' 
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                <span style={{ fontSize: 14, opacity: 0.9 }}>Résultat net</span>
                <Euro size={20} />
              </div>
              <div style={{ fontSize: 28, fontWeight: 700 }}>
                {resultatPositif ? '+' : ''}{summary?.totals?.resultat_net_eur?.toLocaleString('fr-FR')} €
              </div>
              <div style={{ fontSize: 12, opacity: 0.9, marginTop: 4 }}>
                {resultatPositif ? 'Bénéfice' : 'Déficit'}
              </div>
            </motion.div>

            <motion.div 
              initial={{ opacity: 0, y: 20 }} 
              animate={{ opacity: 1, y: 0 }} 
              transition={{ delay: 0.3 }}
              style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                <span style={{ color: '#64748B', fontSize: 14 }}>Écritures</span>
                <Receipt size={20} color="#8B5CF6" />
              </div>
              <div style={{ fontSize: 28, fontWeight: 700, color: '#0F172A' }}>
                {summary?.entries_count || 0}
              </div>
              <div style={{ fontSize: 12, color: '#64748B', marginTop: 4 }}>
                Mouvements comptables
              </div>
            </motion.div>
          </div>

          {/* Graphique évolution */}
          {chartData.length > 0 && (
            <div style={{ background: 'white', borderRadius: 16, padding: 24, marginBottom: 32, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
              <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20, color: '#0F172A' }}>
                Évolution mensuelle {year}
              </h3>
              <ResponsiveContainer width="100%" height={350}>
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="colorProduits" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#10B981" stopOpacity={0.3}/>
                      <stop offset="95%" stopColor="#10B981" stopOpacity={0}/>
                    </linearGradient>
                    <linearGradient id="colorCharges" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#EF4444" stopOpacity={0.3}/>
                      <stop offset="95%" stopColor="#EF4444" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#E2E8F0" />
                  <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                  <YAxis tickFormatter={v => `${v}€`} tick={{ fontSize: 12 }} />
                  <Tooltip formatter={(value) => [`${value?.toLocaleString('fr-FR')} €`]} />
                  <Legend />
                  <Area type="monotone" dataKey="Produits" stroke="#10B981" fill="url(#colorProduits)" strokeWidth={2} />
                  <Area type="monotone" dataKey="Charges" stroke="#EF4444" fill="url(#colorCharges)" strokeWidth={2} />
                  <Line type="monotone" dataKey="Résultat" stroke="#8B5CF6" strokeWidth={3} dot={{ fill: '#8B5CF6', r: 4 }} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Répartition par compagnie */}
          {summary?.by_insurer?.length > 0 && (
            <div style={{ background: 'white', borderRadius: 16, padding: 24, marginBottom: 32, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
              <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20, color: '#0F172A' }}>
                Répartition par compagnie
              </h3>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 16 }}>
                {summary.by_insurer.map((ins, i) => {
                  const percent = summary.totals.produits_eur > 0 
                    ? Math.round((ins.total_eur / summary.totals.produits_eur) * 100) 
                    : 0
                  return (
                    <motion.div
                      key={ins.insurer}
                      initial={{ opacity: 0, scale: 0.95 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ delay: i * 0.05 }}
                      style={{ 
                        padding: 16, 
                        background: '#F8FAFC', 
                        borderRadius: 12,
                        border: '1px solid #E2E8F0'
                      }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                        <Building2 size={16} color="#8B5CF6" />
                        <span style={{ fontWeight: 500, color: '#0F172A', fontSize: 14 }}>{ins.insurer}</span>
                      </div>
                      <div style={{ fontSize: 20, fontWeight: 700, color: '#10B981' }}>
                        {ins.total_eur?.toLocaleString('fr-FR')} €
                      </div>
                      <div style={{ marginTop: 8 }}>
                        <div style={{ height: 4, background: '#E2E8F0', borderRadius: 2, overflow: 'hidden' }}>
                          <div style={{ height: '100%', width: `${percent}%`, background: 'linear-gradient(90deg, #8B5CF6 0%, #06B6D4 100%)', borderRadius: 2 }} />
                        </div>
                        <div style={{ fontSize: 11, color: '#64748B', marginTop: 4 }}>{percent}% du CA</div>
                      </div>
                    </motion.div>
                  )
                })}
              </div>
            </div>
          )}

          {/* Dernières écritures */}
          <div style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <h3 style={{ fontSize: 16, fontWeight: 600, color: '#0F172A', margin: 0 }}>
                Dernières écritures
              </h3>
              <button 
                onClick={loadData}
                style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '6px 12px', background: '#F1F5F9', border: 'none', borderRadius: 6, cursor: 'pointer' }}
              >
                <RefreshCw size={14} color="#64748B" />
              </button>
            </div>

            {entries.length === 0 ? (
              <div style={{ padding: 40, textAlign: 'center', color: '#64748B' }}>
                <FileText size={48} style={{ marginBottom: 16, opacity: 0.3 }} />
                <p>Aucune écriture comptable</p>
                <p style={{ fontSize: 13 }}>Utilisez "Générer écritures" pour créer les écritures depuis vos commissions</p>
              </div>
            ) : (
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
