                onClick={() => copyToClipboard(ex.code, `ex-${i}`)}
                style={{
                  background: 'rgba(139,92,246,0.15)',
                  border: '1px solid rgba(139,92,246,0.3)',
                  borderRadius: 6,
                  padding: '4px 10px',
                  color: '#a78bfa',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6,
                  fontSize: 12
                }}
              >
                {copiedId === `ex-${i}` ? <Check size={14} /> : <Copy size={14} />}
                {copiedId === `ex-${i}` ? 'Copié' : 'Copier'}
              </button>
            </div>
            <pre style={{
              background: 'rgba(0,0,0,0.5)',
              padding: 16,
              borderRadius: 10,
              overflow: 'auto',
              margin: 0,
