/**
 * SignaturesV2 — LOT 20
 * Page de gestion des signatures électroniques (Yousign)
 */

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FileSignature, Clock, CheckCircle2, XCircle, AlertTriangle, Download, RefreshCw, Send, Search, Filter, MoreHorizontal } from 'lucide-react';
import {
  AuroraPageHeader,
  AuroraCard,
  AuroraBadge,
  AuroraButton,
  AuroraSkeleton,
  AuroraEmptyState,
  useToast,
} from '../../components/aurora';

const STATUS_CONFIG = {
  sent_to_sign: { label: 'En attente', color: 'amber', icon: Clock },
  pending: { label: 'En attente', color: 'amber', icon: Clock },
  signed: { label: 'Signé', color: 'emerald', icon: CheckCircle2 },
  refused: { label: 'Refusé', color: 'rose', icon: XCircle },
  expired: { label: 'Expiré', color: 'gray', icon: AlertTriangle },
  cancelled: { label: 'Annulé', color: 'gray', icon: XCircle },
};

export default function SignaturesV2() {
  const [signatures, setSignatures] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const { showToast } = useToast();

  const fetchData = async () => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      const [sigRes, statsRes] = await Promise.all([
        fetch(`/api/signatures${filter !== 'all' ? `?status=${filter}` : ''}`, { headers }),
        fetch('/api/signatures/stats', { headers }),
      ]);

      if (sigRes.ok) {
        const data = await sigRes.json();
        setSignatures(data.signatures || []);
      }

      if (statsRes.ok) {
        setStats(await statsRes.json());
      }
    } catch (err) {
      showToast('Erreur de chargement', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [filter]);

  const handleRemind = async (id) => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/signatures/${id}/remind`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        showToast('Relance envoyée', 'success');
      } else {
        throw new Error();
      }
    } catch {
      showToast('Erreur lors de la relance', 'error');
    }
  };

  const handleDownload = async (id, name) => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/signatures/${id}/download`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const blob = await res.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = name || 'document_signe.pdf';
        a.click();
        URL.revokeObjectURL(url);
      }
    } catch {
      showToast('Erreur de téléchargement', 'error');
    }
  };

  const handleRefreshStatus = async (id) => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/signatures/${id}/status`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        fetchData();
        showToast('Statut mis à jour', 'info');
      }
    } catch {
      showToast('Erreur de rafraîchissement', 'error');
    }
  };

  const filteredSignatures = signatures.filter(s =>
    search === '' ||
    s.signer_email?.toLowerCase().includes(search.toLowerCase()) ||
    s.signer_name?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div style={{ padding: 'var(--aurora-space-6)', maxWidth: 1400, margin: '0 auto' }}>
      <AuroraPageHeader
        title="Signatures Électroniques"
        subtitle="Gérez vos demandes de signature Yousign"
        icon={FileSignature}
      />

      {/* Stats */}
      {stats && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 'var(--aurora-space-4)', marginBottom: 'var(--aurora-space-6)' }}>
          {[
            { label: 'En attente', value: stats.pending || 0, color: '#f59e0b' },
            { label: 'Signées', value: stats.signed || 0, color: '#10b981' },
            { label: 'Refusées', value: stats.refused || 0, color: '#f43f5e' },
            { label: 'Total', value: stats.total || 0, color: '#6366f1' },
          ].map((s, i) => (
            <motion.div
              key={s.label}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.1 }}
            >
              <AuroraCard style={{ textAlign: 'center', padding: 'var(--aurora-space-4)' }}>
                <div style={{ fontSize: 28, fontWeight: 700, color: s.color }}>{s.value}</div>
                <div style={{ fontSize: 12, color: 'var(--aurora-text-secondary)' }}>{s.label}</div>
              </AuroraCard>
            </motion.div>
          ))}
        </div>
      )}

      {/* Filtres */}
      <div style={{ display: 'flex', gap: 'var(--aurora-space-3)', marginBottom: 'var(--aurora-space-4)', flexWrap: 'wrap' }}>
        <div style={{ position: 'relative', flex: 1, minWidth: 200 }}>
          <Search size={16} style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: 'var(--aurora-text-tertiary)' }} />
          <input
            type="text"
            placeholder="Rechercher par email ou nom..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{
              width: '100%',
              padding: '10px 12px 10px 36px',
              background: 'var(--aurora-bg-secondary)',
              border: '1px solid var(--aurora-border)',
              borderRadius: 8,
              color: 'var(--aurora-text-primary)',
              fontSize: 14,
            }}
          />
        </div>
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{
            padding: '10px 16px',
            background: 'var(--aurora-bg-secondary)',
            border: '1px solid var(--aurora-border)',
            borderRadius: 8,
            color: 'var(--aurora-text-primary)',
            fontSize: 14,
          }}
        >
          <option value="all">Tous les statuts</option>
          <option value="pending">En attente</option>
          <option value="sent_to_sign">Envoyées</option>
          <option value="signed">Signées</option>
          <option value="refused">Refusées</option>
          <option value="expired">Expirées</option>
        </select>
      </div>

      {/* Liste */}
      {loading ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--aurora-space-3)' }}>
          {[1, 2, 3].map(i => <AuroraSkeleton key={i} height={80} />)}
        </div>
      ) : filteredSignatures.length === 0 ? (
        <AuroraEmptyState
          icon={FileSignature}
          title="Aucune signature"
          description="Les demandes de signature apparaîtront ici"
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--aurora-space-3)' }}>
          <AnimatePresence>
            {filteredSignatures.map((sig, idx) => {
              const config = STATUS_CONFIG[sig.status] || STATUS_CONFIG.pending;
              const StatusIcon = config.icon;

              return (
                <motion.div
                  key={sig.id}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: 20 }}
                  transition={{ delay: idx * 0.05 }}
                >
                  <AuroraCard style={{ padding: 'var(--aurora-space-4)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 'var(--aurora-space-3)' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--aurora-space-3)' }}>
                        <div style={{
                          width: 40,
                          height: 40,
                          borderRadius: 10,
                          background: `linear-gradient(135deg, var(--aurora-${config.color}-500) 0%, var(--aurora-${config.color}-600) 100%)`,
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                        }}>
                          <StatusIcon size={20} color="white" />
                        </div>
                        <div>
                          <div style={{ fontWeight: 600, color: 'var(--aurora-text-primary)' }}>
                            {sig.signer_name || sig.signer_email}
                          </div>
                          <div style={{ fontSize: 12, color: 'var(--aurora-text-tertiary)' }}>
                            {sig.signer_email}
                          </div>
                        </div>
                      </div>

                      <AuroraBadge color={config.color}>{config.label}</AuroraBadge>

                      <div style={{ fontSize: 12, color: 'var(--aurora-text-tertiary)' }}>
                        {new Date(sig.created_at).toLocaleDateString('fr-FR')}
                      </div>

                      <div style={{ display: 'flex', gap: 'var(--aurora-space-2)' }}>
                        {sig.status === 'signed' && (
                          <AuroraButton
                            variant="ghost"
                            size="sm"
                            icon={Download}
                            onClick={() => handleDownload(sig.id, `${sig.signer_name}_signe.pdf`)}
                          >
                            Télécharger
                          </AuroraButton>
                        )}
                        {(sig.status === 'pending' || sig.status === 'sent_to_sign') && (
                          <>
                            <AuroraButton
                              variant="ghost"
                              size="sm"
                              icon={Send}
                              onClick={() => handleRemind(sig.id)}
                            >
                              Relancer
                            </AuroraButton>
                            <AuroraButton
                              variant="ghost"
                              size="sm"
                              icon={RefreshCw}
                              onClick={() => handleRefreshStatus(sig.id)}
                            >
                              Actualiser
                            </AuroraButton>
                          </>
                        )}
                      </div>
                    </div>
                  </AuroraCard>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { AlertTriangle, Plus, Calendar, FileText, CheckCircle, XCircle, Clock, ChevronRight, Search, Filter, User, Car, Home, Heart, Shield, Sparkles } from 'lucide-react'
import api from '../../api'

const CLAIM_TYPES = {
  auto_collision: { label: 'Auto - Collision', icon: Car, color: '#EF4444' },
  auto_vol: { label: 'Auto - Vol', icon: Car, color: '#F97316' },
  auto_bris_glace: { label: 'Auto - Bris de glace', icon: Car, color: '#F59E0B' },
  habitation_degat_eaux: { label: 'Habitation - Degat des eaux', icon: Home, color: '#3B82F6' },
  habitation_incendie: { label: 'Habitation - Incendie', icon: Home, color: '#EF4444' },
  habitation_vol: { label: 'Habitation - Vol', icon: Home, color: '#F97316' },
  sante: { label: 'Sante', icon: Heart, color: '#EC4899' },
  prevoyance: { label: 'Prevoyance', icon: Shield, color: '#8B5CF6' },
  responsabilite_civile: { label: 'Responsabilite civile', icon: Shield, color: '#06B6D4' },
  autre: { label: 'Autre', icon: FileText, color: '#64748B' },
}

const STATUS_LABELS = {
  opened: { label: 'Ouvert', color: '#F59E0B', icon: Clock },
  in_progress: { label: 'En cours', color: '#3B82F6', icon: Clock },
  pending_docs: { label: 'En attente docs', color: '#F97316', icon: FileText },
  settled: { label: 'Regle', color: '#10B981', icon: CheckCircle },
  rejected: { label: 'Rejete', color: '#EF4444', icon: XCircle },
  closed: { label: 'Cloture', color: '#64748B', icon: CheckCircle },
}

export default function SinistresV2() {
  const [claims, setClaims] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [filterStatus, setFilterStatus] = useState('')
  const [showModal, setShowModal] = useState(false)
  const [newClaim, setNewClaim] = useState({ client_id: '', type: 'autre', description: '', amount: '' })

  useEffect(() => {
    loadClaims()
  }, [filterStatus])

  async function loadClaims() {
    try {
      setLoading(true)
      const params = filterStatus ? { status: filterStatus } : {}
      const res = await api.get('/claims', { params })
      setClaims(res.data || [])
    } catch (err) {
      console.error('Failed to load claims:', err)
    } finally {
      setLoading(false)
    }
  }

  async function createClaim() {
    try {
      await api.post('/claims', newClaim)
      setShowModal(false)
      setNewClaim({ client_id: '', type: 'autre', description: '', amount: '' })
      loadClaims()
    } catch (err) {
      alert('Erreur: ' + (err.response?.data?.message || err.message))
    }
  }

  const filtered = claims.filter(c => {
    const q = search.toLowerCase()
    return !q || c.first_name?.toLowerCase().includes(q) || c.last_name?.toLowerCase().includes(q) || c.type?.toLowerCase().includes(q)
  })

  return (
    <div style={{ padding: '24px', maxWidth: 1400, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 32 }}>
        <div>
          <h1 style={{ fontSize: 28, fontWeight: 700, color: '#0F172A', margin: 0, display: 'flex', alignItems: 'center', gap: 12 }}>
            <AlertTriangle size={28} color="#F59E0B" />
            Sinistres
          </h1>
          <p style={{ color: '#64748B', marginTop: 4 }}>{claims.length} sinistre(s) enregistre(s)</p>
        </div>
        <button onClick={() => setShowModal(true)} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 24px', background: 'linear-gradient(135deg, #8B5CF6 0%, #06B6D4 100%)', color: 'white', border: 'none', borderRadius: 12, fontSize: 15, fontWeight: 600, cursor: 'pointer' }}>
          <Plus size={18} /> Nouveau sinistre
        </button>
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 24 }}>
        <div style={{ flex: 1, position: 'relative' }}>
          <Search size={18} style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: '#94A3B8' }} />
          <input type="text" placeholder="Rechercher par client ou type..." value={search} onChange={e => setSearch(e.target.value)} style={{ width: '100%', padding: '12px 12px 12px 40px', border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14 }} />
        </div>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} style={{ padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14, background: 'white', cursor: 'pointer' }}>
          <option value="">Tous les statuts</option>
          {Object.entries(STATUS_LABELS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
        </select>
      </div>

      {/* Claims List */}
      {loading ? (
        <div style={{ textAlign: 'center', padding: 60, color: '#64748B' }}>Chargement...</div>
      ) : filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: 60, color: '#64748B' }}>
          <AlertTriangle size={48} style={{ marginBottom: 16, opacity: 0.5 }} />
          <p>Aucun sinistre trouve</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {filtered.map(claim => {
            const typeInfo = CLAIM_TYPES[claim.type] || CLAIM_TYPES.autre
            const statusInfo = STATUS_LABELS[claim.status] || STATUS_LABELS.opened
            const TypeIcon = typeInfo.icon
            const StatusIcon = statusInfo.icon
            return (
              <motion.div key={claim.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', alignItems: 'center', gap: 16, padding: 20, background: 'white', borderRadius: 16, border: '1px solid #E2E8F0', cursor: 'pointer' }} whileHover={{ y: -2, boxShadow: '0 8px 30px rgba(0,0,0,0.08)' }}>
                <div style={{ width: 48, height: 48, borderRadius: 12, background: typeInfo.color + '15', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <TypeIcon size={24} color={typeInfo.color} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600, color: '#0F172A', marginBottom: 4 }}>{claim.first_name} {claim.last_name}</div>
                  <div style={{ fontSize: 13, color: '#64748B' }}>{typeInfo.label}</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '6px 12px', borderRadius: 20, background: statusInfo.color + '15', color: statusInfo.color, fontSize: 13, fontWeight: 500 }}>
                    <StatusIcon size={14} />
                    {statusInfo.label}
                  </div>
                  <div style={{ fontSize: 12, color: '#94A3B8', marginTop: 4 }}>{new Date(claim.opened_at).toLocaleDateString('fr-FR')}</div>
                </div>
                {claim.amount && <div style={{ fontWeight: 600, color: '#0F172A', fontSize: 16 }}>{Number(claim.amount).toLocaleString('fr-FR')} EUR</div>}
                <ChevronRight size={20} color="#CBD5E1" />
              </motion.div>
            )
          })}
        </div>
      )}

      {/* Modal */}
      <AnimatePresence>
        {showModal && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }} onClick={() => setShowModal(false)}>
            <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} onClick={e => e.stopPropagation()} style={{ background: 'white', borderRadius: 20, padding: 32, width: '100%', maxWidth: 480 }}>
              <h2 style={{ fontSize: 20, fontWeight: 700, marginBottom: 24 }}>Nouveau sinistre</h2>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 6, color: '#475569' }}>ID Client</label>
                  <input type="number" value={newClaim.client_id} onChange={e => setNewClaim({ ...newClaim, client_id: e.target.value })} placeholder="ID du client" style={{ width: '100%', padding: 12, border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14 }} />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 6, color: '#475569' }}>Type de sinistre</label>
                  <select value={newClaim.type} onChange={e => setNewClaim({ ...newClaim, type: e.target.value })} style={{ width: '100%', padding: 12, border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14, background: 'white' }}>
                    {Object.entries(CLAIM_TYPES).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 6, color: '#475569' }}>Description</label>
                  <textarea value={newClaim.description} onChange={e => setNewClaim({ ...newClaim, description: e.target.value })} placeholder="Description du sinistre..." rows={3} style={{ width: '100%', padding: 12, border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14, resize: 'vertical' }} />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 6, color: '#475569' }}>Montant estime (EUR)</label>
                  <input type="number" value={newClaim.amount} onChange={e => setNewClaim({ ...newClaim, amount: e.target.value })} placeholder="0.00" style={{ width: '100%', padding: 12, border: '1px solid #E2E8F0', borderRadius: 10, fontSize: 14 }} />
                </div>
              </div>
              <div style={{ display: 'flex', gap: 12, marginTop: 24 }}>
                <button onClick={() => setShowModal(false)} style={{ flex: 1, padding: 14, background: '#F1F5F9', border: 'none', borderRadius: 10, fontSize: 15, fontWeight: 500, cursor: 'pointer' }}>Annuler</button>
                <button onClick={createClaim} style={{ flex: 1, padding: 14, background: 'linear-gradient(135deg, #8B5CF6 0%, #06B6D4 100%)', color: 'white', border: 'none', borderRadius: 10, fontSize: 15, fontWeight: 600, cursor: 'pointer' }}>Creer</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

import { useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mic, Upload, Play, Pause, FileAudio, Clock, User, CheckCircle, ChevronRight, X } from 'lucide-react';
import { AuroraPageHeader, AuroraCard, AuroraButton, AuroraBadge, AuroraSkeleton, AuroraEmptyState, AuroraDialog, useToast } from '../../components/aurora';

const API_BASE = '/api';
const getToken = () => localStorage.getItem('token');

export function VoiceV2() {
  const toast = useToast();
  const fileRef = useRef(null);
  const [intakes, setIntakes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [selected, setSelected] = useState(null);
  const [dragOver, setDragOver] = useState(false);

  useEffect(() => {
    fetch(`${API_BASE}/voice/intakes`, { headers: { Authorization: `Bearer ${getToken()}` } })
      .then(r => r.json())
      .then(d => setIntakes(d.intakes || d || []))
      .catch(() => toast.error('Erreur chargement'))
      .finally(() => setLoading(false));
  }, []);

  const upload = async (file) => {
    if (!file) return;
    setUploading(true);
    const form = new FormData();
    form.append('audio', file);
    try {
      const res = await fetch(`${API_BASE}/voice/upload`, { method: 'POST', headers: { Authorization: `Bearer ${getToken()}` }, body: form });
      const intake = await res.json();
      setIntakes(prev => [intake, ...prev]);
      toast.success('Audio uploadé et en cours de traitement');
    } catch (e) { toast.error('Erreur upload'); }
    setUploading(false);
  };

  const handleDrop = (e) => { e.preventDefault(); setDragOver(false); upload(e.dataTransfer.files[0]); };

  const applyData = async (intakeId) => {
    try {
      await fetch(`${API_BASE}/voice/intakes/${intakeId}/apply`, { method: 'POST', headers: { Authorization: `Bearer ${getToken()}` } });
      toast.success('Données appliquées au client');
      setSelected(null);
    } catch (e) { toast.error('Erreur application'); }
  };

  return (
    <div style={{ padding: 'var(--aurora-space-6)', maxWidth: 1400, margin: '0 auto' }}>
      <AuroraPageHeader title="Voice Intake" subtitle="Transcription et extraction automatique depuis l'audio" />
      <motion.div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        onClick={() => fileRef.current?.click()}
        style={{ padding: 'var(--aurora-space-8)', marginBottom: 'var(--aurora-space-6)', background: dragOver ? 'var(--aurora-bg-hover)' : 'var(--aurora-bg-card)', border: `2px dashed ${dragOver ? 'var(--aurora-accent)' : 'var(--aurora-border-subtle)'}`, borderRadius: 'var(--aurora-radius-xl)', textAlign: 'center', cursor: 'pointer', transition: 'all 0.2s' }}
        whileHover={{ borderColor: 'var(--aurora-border-hover)' }}
      >
        <input ref={fileRef} type="file" accept="audio/*" hidden onChange={(e) => upload(e.target.files?.[0])} />
        <Upload size={40} style={{ color: 'var(--aurora-text-muted)', marginBottom: 'var(--aurora-space-3)' }} />
        <div style={{ fontSize: 'var(--aurora-font-lg)', fontWeight: 600, color: 'var(--aurora-text-primary)', marginBottom: 'var(--aurora-space-1)' }}>
          {uploading ? 'Upload en cours...' : 'Glissez un fichier audio ici'}
        </div>
        <div style={{ fontSize: 'var(--aurora-font-sm)', color: 'var(--aurora-text-secondary)' }}>ou cliquez pour sélectionner (MP3, WAV, M4A)</div>
      </motion.div>

      <h3 style={{ fontSize: 'var(--aurora-font-lg)', fontWeight: 600, marginBottom: 'var(--aurora-space-3)' }}>Intakes récents</h3>
      {loading ? <AuroraSkeleton lines={4} /> : intakes.length === 0 ? <AuroraEmptyState icon={FileAudio} title="Aucun intake" description="Uploadez votre premier fichier audio" /> : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--aurora-space-2)' }}>
          {intakes.map((intake, i) => (
            <motion.div key={intake.id || i} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.05 }} onClick={() => setSelected(intake)} style={{ display: 'flex', alignItems: 'center', gap: 'var(--aurora-space-3)', padding: 'var(--aurora-space-4)', background: 'var(--aurora-bg-card)', border: '1px solid var(--aurora-border-subtle)', borderRadius: 'var(--aurora-radius-md)', cursor: 'pointer' }} whileHover={{ background: 'var(--aurora-bg-hover)', x: 4 }}>
              <div style={{ width: 44, height: 44, borderRadius: 'var(--aurora-radius-md)', background: 'var(--aurora-bg-subtle)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <FileAudio size={22} style={{ color: 'var(--aurora-accent)' }} />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 500, marginBottom: 4 }}>{intake.filename || `Intake #${intake.id}`}</div>
                <div style={{ display: 'flex', gap: 'var(--aurora-space-3)', fontSize: 'var(--aurora-font-xs)', color: 'var(--aurora-text-muted)' }}>
                  <span><Clock size={12} style={{ marginRight: 4, verticalAlign: 'middle' }} />{intake.duration || '2:34'}</span>
                  {intake.clientName && <span><User size={12} style={{ marginRight: 4, verticalAlign: 'middle' }} />{intake.clientName}</span>}
                </div>
              </div>
              <AuroraBadge variant={intake.status === 'processed' ? 'success' : intake.status === 'processing' ? 'warning' : 'default'} dot>{intake.status || 'traité'}</AuroraBadge>
              <ChevronRight size={16} style={{ color: 'var(--aurora-text-muted)' }} />
            </motion.div>
          ))}
        </div>
      )}

      <AuroraDialog open={!!selected} onClose={() => setSelected(null)} title="Détail de l'intake" size="lg" footer={<><AuroraButton variant="ghost" onClick={() => setSelected(null)}>Fermer</AuroraButton><AuroraButton onClick={() => applyData(selected?.id)}><CheckCircle size={16} style={{ marginRight: 8 }} />Appliquer au client</AuroraButton></>}>
        {selected && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--aurora-space-4)' }}>
            <div><h4 style={{ margin: '0 0 var(--aurora-space-2)', fontSize: 'var(--aurora-font-base)', fontWeight: 600 }}>Transcription</h4><div style={{ padding: 'var(--aurora-space-3)', background: 'var(--aurora-bg-subtle)', borderRadius: 'var(--aurora-radius-md)', fontSize: 'var(--aurora-font-sm)', lineHeight: 1.6, maxHeight: 200, overflowY: 'auto' }}>{selected.transcript || 'Transcription non disponible'}</div></div>
            <div><h4 style={{ margin: '0 0 var(--aurora-space-2)', fontSize: 'var(--aurora-font-base)', fontWeight: 600 }}>Données extraites</h4><div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 'var(--aurora-space-2)' }}>
              {Object.entries(selected.extracted_data || selected.extractedData || {}).map(([k, v]) => (
                <div key={k} style={{ padding: 'var(--aurora-space-2)', background: 'var(--aurora-bg-subtle)', borderRadius: 'var(--aurora-radius-sm)' }}>
                  <div style={{ fontSize: 'var(--aurora-font-xs)', color: 'var(--aurora-text-muted)', textTransform: 'capitalize' }}>{k.replace(/_/g, ' ')}</div>
                  <div style={{ fontWeight: 500 }}>{String(v)}</div>
                </div>
              ))}
            </div></div>
          </div>
        )}
      </AuroraDialog>
    </div>
  );
}

export default VoiceV2;

